EXE=os.path.abspath("./executable")
def run(args, inp):
    return subprocess.run([EXE]+args, input=inp, capture_output=True).stdout

class Bits:
    def __init__(self,data):
        self.d=data; self.pos=0 # bit pos
    def get(self,n):
        v=0
        for i in range(n):
            byte=self.d[self.pos//8]
            bit=(byte>>(self.pos&7))&1
            v|=bit<<i
            self.pos+=1
        return v
    def align(self):
        self.pos=(self.pos+7)//8*8

class Huff:
    def __init__(self,lengths):
        self.map={}
        # canonical
        maxl=max(lengths) if lengths else 0
        bl=[0]*(maxl+1)
        for l in lengths:
            if l: bl[l]+=1
        code=0; nextc=[0]*(maxl+2)
        for bits in range(1,maxl+1):
            code=(code+bl[bits-1])<<1; nextc[bits]=code
        for sym,l in enumerate(lengths):
            if l:
                self.map[(l,nextc[l])]=sym; nextc[l]+=1
        self.maxl=maxl
    def decode(self,b):
        code=0
        for l in range(1,self.maxl+1):
            code=(code<<1)|b.get(1)
            if (l,code) in self.map:
                return self.map[(l,code)]
        raise ValueError("bad huff")

