                order=[16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15]
                cl=[0]*19
                for i in range(hclen): cl[order[i]]=b.get(3)
                ch=Huff(cl)
                lengths=[]
                while len(lengths)<hlit+hdist:
                    sym=ch.decode(b)
                    if sym<16: lengths.append(sym)
                    elif sym==16:
                        rep=3+b.get(2); lengths.extend([lengths[-1]]*rep)
                    elif sym==17:
                        rep=3+b.get(3); lengths.extend([0]*rep)
                    elif sym==18:
                        rep=11+b.get(7); lengths.extend([0]*rep)
                litlen=lengths[:hlit]; distlen=lengths[hlit:]
                print(f"   dynamic hlit={hlit} hdist={hdist} hclen={hclen} after trees bit={b.pos}")
            lh=Huff(litlen); dh=Huff(distlen)
            nsym=0
            while True:
                sym=lh.decode(b); nsym+=1
                if sym<256:
                    outpos+=1
                elif sym==256:
                    break
                else:
                    li=sym-257
                    length=length_base[li]+b.get(length_extra[li])
                    dsym=dh.decode(b)
                    dist=dist_base[dsym]+b.get(dist_extra[dsym])
                    outpos+=length
            print(f"   symbols={nsym} end_bit={b.pos} byte={b.pos//8}.{b.pos%8} outpos_end={outpos}")
        else:
            print(" reserved"); break
        idx+=1
        if bfinal:
            print(f" FINAL end bit={b.pos} total bytes raw={len(raw)}")
            break
        if idx>20: break

