import ast, zlib
data=open("/tmp/rsync_data.bin","rb").read()
bounds=ast.literal_eval(open("/tmp/rsync_bounds_true.txt").read())
pos=bounds[1:-1]

def const_bits(vals, width=32):
    cs=[]
    for bit in range(width):
        b=(vals[0]>>bit)&1
        if all(((v>>bit)&1)==b for v in vals): cs.append(bit)
    return cs

def test(name,vals):
    cs=const_bits(vals)
    if len(cs)>=2:
        print("hit",name,"constbits",cs,"vals first",hex(vals[0]))
        return True
    return False

for N in [4,8,12,16,20,24,32,48,64,128,256]:
    test(f"crc N={N}",[zlib.crc32(data[b-N:b]) for b in pos])
    test(f"adler N={N}",[zlib.adler32(data[b-N:b]) for b in pos])

# Possibly offset windows: hash of next N bytes after boundary, or window ending at b+delta
for N in [4,8,16,32]:
    for delta in range(-32,33,4):
        if delta==0: continue
        vals=[]
        ok=True
        for b in pos:
            start=b+delta-N; end=b+delta
            if start<0: ok=False; break
            vals.append(zlib.crc32(data[start:end]))
        if ok: test(f"crc N={N} endDelta={delta}",vals)

Ps=[31,33,37,39,41,53,131,257, 65599]
for N in [3,4,5,6,7,8,9,10,12,16,20,24,32,48,64,96,128]:
    ws=[data[b-N:b] for b in pos]
    for P in Ps:
        for variant in range(6):
            vals=[]
            for w in ws:
                if variant==0:
                    h=0
                    for c in w: h=(h*P+c)&0xffffffff
                elif variant==1:
                    h=0
                    for c in w: h=(h*P ^ c)&0xffffffff
                elif variant==2:
                    h=5381
                    for c in w: h=(h*P+c)&0xffffffff
                elif variant==3:
                    h=0
                    for c in w: h=((h<<5)+(h>>27)^c)&0xffffffff if P==31 else (h*P+c)&0xffffffff
                elif variant==4:
