/* ---------- exceptions ---------- */
enum ex_kind { EX_NONE = 0, EX_ABORT = 1, EX_SKIP = 2, EX_WARN = 3 };
enum warn_kind { WARN_ZLIB = 1, WARN_ZIP = 2 };
static struct {
    int kind;
    int code;
    int warn;
    char *msg;
} exc_state;
static jmp_buf *cur_jmp = NULL;

static char *xstrdup(const char *s);
static void *xmalloc(size_t n);
static void *xrealloc(void *p, size_t n);

static void throw_v(int kind, int code, int warn, const char *fmt, va_list ap) {
    char *msg = NULL;
    if (vasprintf(&msg, fmt, ap) < 0)
        msg = xstrdup("out of memory");
    free(exc_state.msg);
    exc_state.kind = kind;
    exc_state.code = code;
    exc_state.warn = warn;
    exc_state.msg = msg;
    if (cur_jmp != NULL)
        longjmp(*cur_jmp, 1);
    /* No handler (should not happen): act like an abort. */
    if (verbosity > 0)
        fprintf(stderr, "%s: abort: %s\n", prog, msg);
    exit(code != 0 ? code : 1);
}
static void throw_abort(int code, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt); throw_v(EX_ABORT, code, 0, fmt, ap); va_end(ap);
}
static void throw_skip(const char *fmt, ...) {
    va_list ap; va_start(ap, fmt); throw_v(EX_SKIP, 1, 0, fmt, ap); va_end(ap);
}
static void throw_warn(int warn, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt); throw_v(EX_WARN, 1, warn, fmt, ap); va_end(ap);
}

static void *xmalloc(size_t n) {
