}

/* ---------- buffered reader / writer ---------- */
typedef struct {
    int fd;
    const char *name;
    unsigned char buf[65536];
    size_t pos, len;
    int eof;
    unsigned char *push;
    size_t push_pos, push_len, push_cap;
} Reader;

static void reader_init(Reader *r, int fd, const char *name) {
    memset(r, 0, sizeof(*r));
    r->fd = fd; r->name = name;
}
static void reader_free(Reader *r) { free(r->push); r->push = NULL; }

static int reader_fill(Reader *r) {
    if (r->pos < r->len) return 1;
    if (r->eof) return 0;
    for (;;) {
        ssize_t n = read(r->fd, r->buf, sizeof(r->buf));
        if (n < 0) {
            if (errno == EINTR) continue;
            int e = errno;
            throw_abort(e, "read error on %s (%s)", r->name, strerror(e));
        }
        if (n == 0) { r->eof = 1; r->pos = r->len = 0; return 0; }
        r->pos = 0; r->len = (size_t)n; return 1;
    }
}
static int rgetc2(Reader *r) {
    if (r->push_pos < r->push_len) return r->push[r->push_pos++];
    if (!reader_fill(r)) return -1;
    return r->buf[r->pos++];
}
static size_t rread(Reader *r, unsigned char *dst, size_t want) {
    size_t got = 0;
    while (got < want) {
        if (r->push_pos < r->push_len) {
            size_t avail = r->push_len - r->push_pos;
            size_t take = avail < (want - got) ? avail : (want - got);
            memcpy(dst + got, r->push + r->push_pos, take);
            r->push_pos += take; got += take; continue;
        }
        if (r->pos < r->len) {
            size_t avail = r->len - r->pos;
            size_t take = avail < (want - got) ? avail : (want - got);
            memcpy(dst + got, r->buf + r->pos, take);
            r->pos += take; got += take; continue;
        }
        if (!reader_fill(r)) break;
    }
    return got;
}
static void runread(Reader *r, const unsigned char *data, size_t len) {
    if (len == 0) return;
    size_t oldavail = r->push_len - r->push_pos;
    size_t need = len + oldavail;
    unsigned char *np = xmalloc(need);
    memcpy(np, data, len);
    if (oldavail) memcpy(np + len, r->push + r->push_pos, oldavail);
    free(r->push);
    r->push = np; r->push_pos = 0; r->push_len = need; r->push_cap = need;
}
static int reader_has_any(Reader *r) {
    if (r->push_pos < r->push_len) return 1;
    if (r->pos < r->len) return 1;
    return reader_fill(r);
}
/* Read an exact number of bytes; return count actually read (short on EOF). */
static size_t rread_exact(Reader *r, unsigned char *dst, size_t want) {
    size_t got = 0;
    while (got < want) {
        size_t n = rread(r, dst + got, want - got);
        if (n == 0) break;
        got += n;
    }
    return got;
}

typedef struct {
    int fd;
    const char *name;
    uint64_t count;
} Writer;
static void writer_init(Writer *w, int fd, const char *name) {
    w->fd = fd; w->name = name; w->count = 0;
}
static void write_all(Writer *w, const void *data, size_t len) {
    const unsigned char *p = (const unsigned char *)data;
    while (len > 0) {
        ssize_t n = write(w->fd, p, len);
        if (n < 0) {
            if (errno == EINTR) continue;
            int e = errno;
            throw_abort(e, "write error on %s (%s)", w->name, strerror(e));
        }
        if (n == 0) {
            throw_abort(EIO, "write error on %s (%s)", w->name, strerror(EIO));
        }
        p += (size_t)n; len -= (size_t)n; w->count += (uint64_t)n;
    }
}
static void wputc1(Writer *w, unsigned char c) { write_all(w, &c, 1); }
static void wput16le(Writer *w, unsigned v) {
