/* Strip a recognised compressed suffix. Returns malloc'd name or NULL. */
static char *strip_suffix(const char *path) {
    size_t len = strlen(path);
    static const struct { const char *suf; size_t n; const char *rep; } tab[] = {
        {".tgz", 4, ".tar"},
        {".zip", 4, ""}, {".ZIP", 4, ""},
        {".gz", 3, ""}, {"-gz", 3, ""}, {".zz", 3, ""}, {"-zz", 3, ""},
        {".z", 2, ""}, {"-z", 2, ""}, {"_z", 2, ""}, {".Z", 2, ""},
    };
    for (size_t i = 0; i < sizeof(tab) / sizeof(tab[0]); i++) {
        if (len > tab[i].n && strcmp(path + len - tab[i].n, tab[i].suf) == 0) {
            size_t keep = len - tab[i].n;
            size_t repl = strlen(tab[i].rep);
            char *out = xmalloc(keep + repl + 1);
