static void process_option_token(TokSrc *src, char *token) {
    /* token starts with '-' and has at least one more char. */
    if (token[1] == '-') {
        const char *name = token + 2;
        for (int i = 0; long_options[i].name; i++) {
            if (strcmp(name, long_options[i].name) == 0) {
                int code = long_options[i].code;
                if (is_param_opt(code)) {
                    const char *param = fetch_param(src, code);
                    apply_option(code, param);
                } else {
                    apply_option(code, NULL);
                }
                return;
            }
        }
        throw_abort(EINVAL, "invalid option: %s", token);
    }
    char *p = token + 1;
    while (*p) {
        unsigned char c = (unsigned char)*p;
        if (c >= '0' && c <= '9') {
            unsigned long val = 0;
            int over = 0;
            while (*p >= '0' && *p <= '9') {
                unsigned d = (unsigned)(*p - '0');
                if (val > 1000000UL) over = 1;
                else val = val * 10 + d;
                p++;
