            if (c == 'C' || c == 'S') {
                if (*p != '\0')
                    throw_abort(EINVAL, "invalid usage: -%c must be followed by space", c);
                param = fetch_param(src, c);
            } else if (*p != '\0') {
                param = p;
                p += strlen(p);
            } else {
                param = fetch_param(src, c);
            }
            apply_option(c, param);
        } else {
            apply_option(c, NULL);
        }
    }
}

static void process_env_var(const char *var_name) {
    const char *val = getenv(var_name);
    if (val == NULL) return;
    char *copy = xstrdup(val);
    /* Tokenise on space/tab with pigz's exact do/while behaviour. */
    char **tokens = NULL;
    int ntok = 0, cap = 0;
    char *p = copy;
    while (*p) {
        while (*p == ' ' || *p == '\t') p++;
        char *tok = p;
        while (*p && *p != ' ' && *p != '\t') p++;
        if (*p) *p++ = '\0';
        if (ntok == cap) { cap = cap ? cap * 2 : 16; tokens = xrealloc(tokens, (size_t)cap * sizeof(char *)); }
        tokens[ntok++] = tok;
    }
    TokSrc src;
    src.tokens = tokens; src.count = ntok; src.idx = 0; src.is_env = 1; src.env_name = var_name;
    while (src.idx < src.count) {
        char *token = src.tokens[src.idx++];
        if (token[0] != '-' || token[1] == '\0')
            throw_abort(EINVAL, "cannot provide files in %s environment variable", var_name);
        process_option_token(&src, token);
    }
    free(tokens);
    free(copy);
}
