    case 'N': head_name_flag = 1; head_time_flag = 1; head_name_set = 1; head_time_set = 1; break;
    case 'O': oneblock_opt = 1; break;
    case 'p': {
        unsigned long n = num_param(param);
        int pi = (int)n;
        if (pi < 1)
            throw_abort(EINVAL, "invalid number of processes: %s", param);
        if (n >= (1UL << 30))
