    case 'r': recurse_opt = 1; break;
    case 'R': rsync_opt = 1; break;
    case 'S':
        if (param[0] == '\0')
            throw_abort(EINVAL, "suffix cannot be empty");
        suffix_opt = xstrdup(param);
