    case 't': decode_mode = 2; break;
    case 'U': strategy_opt = Z_RLE; break;
    case 'v': verbosity++; break;
    case 'V':
        printf("pigz " PIGZ_VERSION "\n");
        if (verbosity > 1)
            printf("zlib %s\n", zlibVersion());
        exit(0);
    case 'Y': sync_opt = 1; break;
    case 'z': format_opt = 1; suffix_opt = (char *)".zz"; break;
    case 'Z': throw_abort(EINVAL, "invalid option: LZW output not supported: -Z"); break;
    default:
