static void process_option_token(TokSrc *src, char *token) {
    /* token starts with '-' and has at least one more char. */
    if (token[1] == '-') {
        const char *name = token + 2;
        for (int i = 0; long_options[i].name; i++) {
            if (strcmp(name, long_options[i].name) == 0) {
                int code = long_options[i].code;
                if (is_param_opt(code)) {
                    const char *param = fetch_param(src, code);
                    apply_option(code, param);
                } else {
                    apply_option(code, NULL);
                }
                return;
            }
        }
        throw_abort(EINVAL, "invalid option: %s", token);
    }
    char *p = token + 1;
    while (*p) {
        unsigned char c = (unsigned char)*p;
        if (c >= '0' && c <= '9') {
            unsigned long val = 0;
            int over = 0;
            while (*p >= '0' && *p <= '9') {
                unsigned d = (unsigned)(*p - '0');
                if (val > 1000000UL) over = 1;
                else val = val * 10 + d;
                p++;
            }
            if (over || !((val <= 9) || val == 11))
                throw_abort(EINVAL, "only levels 0..9 and 11 are allowed");
            level_opt = (int)val;
            continue;
        }
        p++;
        if (is_param_opt(c)) {
            const char *param;
            if (c == 'C' || c == 'S') {
                if (*p != '\0')
                    throw_abort(EINVAL, "invalid usage: -%c must be followed by space", c);
                param = fetch_param(src, c);
            } else if (*p != '\0') {
                param = p;
                p += strlen(p);
            } else {
                param = fetch_param(src, c);
            }
            apply_option(c, param);
        } else {
            apply_option(c, NULL);
        }
    }
}

static void process_env_var(const char *var_name) {
    const char *val = getenv(var_name);
    if (val == NULL) return;
    char *copy = xstrdup(val);
    /* Tokenise on space/tab with pigz's exact do/while behaviour. */
    char **tokens = NULL;
    int ntok = 0, cap = 0;
    char *p = copy;
    while (*p) {
        while (*p == ' ' || *p == '\t') p++;
        char *tok = p;
        while (*p && *p != ' ' && *p != '\t') p++;
        if (*p) *p++ = '\0';
        if (ntok == cap) { cap = cap ? cap * 2 : 16; tokens = xrealloc(tokens, (size_t)cap * sizeof(char *)); }
        tokens[ntok++] = tok;
    }
    TokSrc src;
    src.tokens = tokens; src.count = ntok; src.idx = 0; src.is_env = 1; src.env_name = var_name;
    while (src.idx < src.count) {
        char *token = src.tokens[src.idx++];
        if (token[0] != '-' || token[1] == '\0')
            throw_abort(EINVAL, "cannot provide files in %s environment variable", var_name);
        process_option_token(&src, token);
    }
    free(tokens);
    free(copy);
}
