    int strategy = (level_opt == 11) ? Z_DEFAULT_STRATEGY : strategy_opt;
    if (use_level == 11) use_level = 9;
    int zret = deflateInit2(&strm, use_level, Z_DEFLATED, -15, 8, strategy);
    if (zret == Z_MEM_ERROR) throw_abort(ENOMEM, "out of memory");
    if (zret != Z_OK) throw_abort(EINVAL, "internal compression error");
    if (!is_first && !independent_opt && cc->dict_len > 0) {
        if (deflateSetDictionary(&strm, cc->dict, (uInt)cc->dict_len) != Z_OK)
            throw_abort(EINVAL, "internal compression error");
