    if (level_opt == 11 && iterations_opt <= 0) {
        /* Fall through to normal zlib flow would emit real data; handled by caller. */
    }

    if (is_last) {
        deflate_flush_loop(&strm, Z_FINISH, cc->writer, outbuf, outcap);
    } else if (independent_opt) {
        deflate_flush_loop(&strm, Z_SYNC_FLUSH, cc->writer, outbuf, outcap);
        static const unsigned char marker[5] = {0x00, 0x00, 0x00, 0xFF, 0xFF};
        write_all(cc->writer, marker, 5);
