        int bits = 0;
        for (;;) {
            strm.next_out = outbuf;
            strm.avail_out = (uInt)outcap;
            int r = deflate(&strm, Z_BLOCK);
            size_t produced = outcap - strm.avail_out;
            if (produced) write_all(cc->writer, outbuf, produced);
            if (r == Z_MEM_ERROR) { free(outbuf); deflateEnd(&strm); throw_abort(ENOMEM, "out of memory"); }
            if (r != Z_OK && r != Z_BUF_ERROR) { free(outbuf); deflateEnd(&strm); throw_abort(EINVAL, "internal compression error"); }
            unsigned pending = 0;
            deflatePending(&strm, &pending, &bits);
            if (strm.avail_in == 0 && pending == 0) break;
            if (r == Z_BUF_ERROR && produced == 0 && strm.avail_in == 0) break;
        }
        if (bits != 0) {
            if (bits & 1) {
                deflate_flush_loop(&strm, Z_SYNC_FLUSH, cc->writer, outbuf, outcap);
            } else {
                /* One partial flush inserts an empty fixed block; then the
                   remaining bits in the bit buffer are known zero bits. */
                unsigned pending = 0; int pbits = bits;
                do {
                    strm.next_out = outbuf;
                    strm.avail_out = (uInt)outcap;
                    int r = deflate(&strm, Z_PARTIAL_FLUSH);
                    size_t produced = outcap - strm.avail_out;
                    if (produced) write_all(cc->writer, outbuf, produced);
                    if (r == Z_MEM_ERROR) { free(outbuf); deflateEnd(&strm); throw_abort(ENOMEM, "out of memory"); }
                    deflatePending(&strm, &pending, &pbits);
                    if (r == Z_BUF_ERROR) break;
                } while (pending != 0);
                append_fixed_empty_blocks(cc->writer, pbits);
            }
        }
    }
    free(outbuf);
    deflateEnd(&strm);
}

/* Emit just empty fixed blocks (used for -11 -I 0 quirk). */
static void emit_empty_block_bits(Writer *w, int is_last, int *curbits_io, unsigned int *cur_io, int final_flag) {
    int bits_seq[10];
    bits_seq[0] = final_flag ? 1 : 0;
    bits_seq[1] = 1; bits_seq[2] = 0;
    for (int i = 3; i < 10; i++) bits_seq[i] = 0;
    int curbits = *curbits_io;
    unsigned int cur = *cur_io;
    for (int i = 0; i < 10; i++) {
        cur |= (unsigned)bits_seq[i] << curbits;
        curbits++;
        if (curbits == 8) { wputc1(w, (unsigned char)cur); cur = 0; curbits = 0; }
    }
    *curbits_io = curbits; *cur_io = cur;
    (void)is_last;
