static void update_dict(CompressCtx *cc, const unsigned char *data, size_t len) {
    if (len >= 32768) {
        memcpy(cc->dict, data + len - 32768, 32768);
        cc->dict_len = 32768;
    } else {
        if (cc->dict_len + len > 32768) {
            size_t drop = (cc->dict_len + len) - 32768;
            memmove(cc->dict, cc->dict + drop, cc->dict_len - drop);
            cc->dict_len -= drop;
        }
        memcpy(cc->dict + cc->dict_len, data, len);
        cc->dict_len += len;
    }
}

static unsigned char zlib_header2_for_level(int lvl) {
    if (lvl == 1) return 0x01;
    if (lvl == 9 || lvl == 11) return 0xDA;
    if (lvl >= 6) return 0x5E;
    return 0x9C;
