static void dos_from_time(time_t t, uint32_t *dostime, uint32_t *dosdate) {
    struct tm tmv;
    localtime_r(&t, &tmv);
    int year = tmv.tm_year + 1900;
    if (year < 1980) { year = 1980; }
    *dostime = (uint32_t)((tmv.tm_hour << 11) | (tmv.tm_min << 5) | (tmv.tm_sec >> 1));
    *dosdate = (uint32_t)(((year - 1980) << 9) | ((tmv.tm_mon + 1) << 5) | tmv.tm_mday);
