/* ---------- header parsing ---------- */
enum form_t { FORM_GZIP = 0, FORM_ZLIB = 1, FORM_ZIP = 2, FORM_LZW = 3 };
typedef struct {
    int form;
    int method;          /* display method (zip encrypted => 256) */
    int method_actual;
    uint32_t check;      /* header check value (zip local crc) */
    uint64_t in_len;     /* zip compressed size from header */
    uint64_t out_len;    /* zip uncompressed size from header */
    int64_t time;        /* signed (as pigz stores it) */
    char *name;          /* stored name, or NULL */
    int name_present;
    int descriptor;      /* zip flag bit 3 */
    int zip64_extra;     /* zip64 extra field was present */
    int lzw_flags;
} Head;

static void head_free_name(Head *h) { free(h->name); h->name = NULL; h->name_present = 0; }

/* Parse helpers that work for both first and subsequent headers.
   Return 1 on a usable header, 0 on "no (further) header".
   For the first header, failures throw EX_SKIP with the precise messages. */
static const char *g_in_display = "<stdin>";

static int hdr_fail_unrec(int subsequent) {
    if (subsequent) return 0;
    throw_skip("%s unrecognized format", g_in_display);
    return 0;
}

static int parse_gzip_header(Reader *r, Head *h, int subsequent) {
    unsigned char hdr[10];
    hdr[0] = 0x1F; hdr[1] = 0x8B;
    if (rread_exact(r, hdr + 2, 8) != 8) return hdr_fail_unrec(subsequent);
    int method = hdr[2];
    int flg = hdr[3];
    if (flg & 0xE0) return hdr_fail_unrec(subsequent);
    h->form = FORM_GZIP;
    h->method = method; h->method_actual = method;
    h->time = (int64_t)(int32_t)get32le(hdr + 4);
    uint32_t crc = (uint32_t)crc32(crc32(0, Z_NULL, 0), hdr, 10);
    if (flg & 4) {
        unsigned char xl[2];
        if (rread_exact(r, xl, 2) != 2) return hdr_fail_unrec(subsequent);
        crc = (uint32_t)crc32(crc, xl, 2);
        unsigned xlen = get16le(xl);
        for (unsigned i = 0; i < xlen; i++) {
            int c = rgetc2(r);
            if (c < 0) return hdr_fail_unrec(subsequent);
            unsigned char uc = (unsigned char)c;
            crc = (uint32_t)crc32(crc, &uc, 1);
        }
    }
    if (flg & 8) {
        size_t cap = 64, len = 0;
        char *name = xmalloc(cap);
        for (;;) {
            int c = rgetc2(r);
            if (c < 0) { free(name); return hdr_fail_unrec(subsequent); }
            unsigned char uc = (unsigned char)c;
            crc = (uint32_t)crc32(crc, &uc, 1);
            if (c == 0) break;
            if (len + 1 >= cap) { cap *= 2; name = xrealloc(name, cap); }
            name[len++] = (char)c;
        }
        name[len] = 0;
        h->name = name; h->name_present = 1;
    }
    if (flg & 16) {
        for (;;) {
            int c = rgetc2(r);
            if (c < 0) return hdr_fail_unrec(subsequent);
            unsigned char uc = (unsigned char)c;
            crc = (uint32_t)crc32(crc, &uc, 1);
            if (c == 0) break;
        }
    }
    if (flg & 2) {
        unsigned char cb[2];
        if (rread_exact(r, cb, 2) != 2) return hdr_fail_unrec(subsequent);
        unsigned want = get16le(cb);
        if (want != (crc & 0xFFFF)) {
            if (subsequent) return 0;
            throw_skip("%s corrupt: header crc error", g_in_display);
        }
    }
    if (method != 8 && subsequent) return 0;
    return 1;
}

static int64_t dos_to_time(uint32_t dostime, uint32_t dosdate) {
    if (dostime == 0 && dosdate == 0)
        return (int64_t)time(NULL);
    struct tm tmv;
    memset(&tmv, 0, sizeof(tmv));
    tmv.tm_year = (int)((dosdate >> 9) & 0x7F) + 80;
    tmv.tm_mon = (int)((dosdate >> 5) & 0xF) - 1;
    tmv.tm_mday = (int)(dosdate & 0x1F);
    tmv.tm_hour = (int)((dostime >> 11) & 0x1F);
    tmv.tm_min = (int)((dostime >> 5) & 0x3F);
    tmv.tm_sec = (int)(dostime & 0x1F) * 2;
    tmv.tm_isdst = -1;
    return (int64_t)mktime(&tmv);
}

static int parse_zip_header(Reader *r, Head *h, int subsequent) {
    unsigned char hdr[26];
    if (rread_exact(r, hdr, 26) != 26) return hdr_fail_unrec(subsequent);
    unsigned flag = get16le(hdr + 2);
    unsigned method = get16le(hdr + 4);
    if (flag & ~0x080F) return hdr_fail_unrec(subsequent);
    uint32_t dostime = get16le(hdr + 6);
    uint32_t dosdate = get16le(hdr + 8);
    uint32_t crc = get32le(hdr + 10);
    uint32_t comp32 = get32le(hdr + 14);
    uint32_t uncomp32 = get32le(hdr + 18);
    unsigned name_len = get16le(hdr + 22);
    unsigned extra_len = get16le(hdr + 24);
    char *name = xmalloc((size_t)name_len + 1);
    if (name_len && rread_exact(r, (unsigned char *)name, name_len) != name_len) { free(name); return hdr_fail_unrec(subsequent); }
    name[name_len] = 0;
    unsigned char *extra = xmalloc(extra_len ? extra_len : 1);
    if (extra_len && rread_exact(r, extra, extra_len) != extra_len) { free(name); free(extra); return hdr_fail_unrec(subsequent); }

    h->form = FORM_ZIP;
    h->method_actual = (int)method;
    h->method = (flag & 1) ? 256 : (int)method;
    h->check = crc;
    h->descriptor = (flag & 8) != 0;
    uint64_t comp = comp32, uncomp = uncomp32;
    int64_t ut_time = 0;
    int have_ut = 0;
    size_t off = 0;
    while (off + 4 <= extra_len) {
        unsigned id = get16le(extra + off);
        unsigned sz = get16le(extra + off + 2);
        if (off + 4 + sz > extra_len) break;
        const unsigned char *pl = extra + off + 4;
        if (id == 0x0001) {
            h->zip64_extra = 1;
            size_t idx = 0;
            if (uncomp32 == 0xFFFFFFFFUL && idx + 8 <= sz) { uncomp = get64le(pl + idx); idx += 8; }
            if (comp32 == 0xFFFFFFFFUL && idx + 8 <= sz) { comp = get64le(pl + idx); idx += 8; }
        } else if (id == 0x5455) {
            if (sz >= 5 && (pl[0] & 1)) {
                ut_time = (int64_t)(int32_t)get32le(pl + 1);
                have_ut = 1;
