    int method_actual;
    uint32_t check;      /* header check value (zip local crc) */
    uint64_t in_len;     /* zip compressed size from header */
    uint64_t out_len;    /* zip uncompressed size from header */
    int64_t time;        /* signed (as pigz stores it) */
    char *name;          /* stored name, or NULL */
    int name_present;
    int descriptor;      /* zip flag bit 3 */
    int zip64_extra;     /* zip64 extra field was present */
    int lzw_flags;
} Head;

static void head_free_name(Head *h) { free(h->name); h->name = NULL; h->name_present = 0; }

/* Parse helpers that work for both first and subsequent headers.
   Return 1 on a usable header, 0 on "no (further) header".
   For the first header, failures throw EX_SKIP with the precise messages. */
