static int hdr_fail_unrec(int subsequent) {
    if (subsequent) return 0;
    throw_skip("%s unrecognized format", g_in_display);
    return 0;
}

static int parse_gzip_header(Reader *r, Head *h, int subsequent) {
    unsigned char hdr[10];
    hdr[0] = 0x1F; hdr[1] = 0x8B;
    if (rread_exact(r, hdr + 2, 8) != 8) return hdr_fail_unrec(subsequent);
    int method = hdr[2];
    int flg = hdr[3];
    if (flg & 0xE0) return hdr_fail_unrec(subsequent);
    h->form = FORM_GZIP;
    h->method = method; h->method_actual = method;
    h->time = (int64_t)(int32_t)get32le(hdr + 4);
    uint32_t crc = (uint32_t)crc32(crc32(0, Z_NULL, 0), hdr, 10);
    if (flg & 4) {
        unsigned char xl[2];
        if (rread_exact(r, xl, 2) != 2) return hdr_fail_unrec(subsequent);
        crc = (uint32_t)crc32(crc, xl, 2);
        unsigned xlen = get16le(xl);
        for (unsigned i = 0; i < xlen; i++) {
            int c = rgetc2(r);
            if (c < 0) return hdr_fail_unrec(subsequent);
            unsigned char uc = (unsigned char)c;
            crc = (uint32_t)crc32(crc, &uc, 1);
