    if (flg & 2) {
        unsigned char cb[2];
        if (rread_exact(r, cb, 2) != 2) return hdr_fail_unrec(subsequent);
        unsigned want = get16le(cb);
        if (want != (crc & 0xFFFF)) {
            if (subsequent) return 0;
            throw_skip("%s corrupt: header crc error", g_in_display);
        }
    }
    if (method != 8 && subsequent) return 0;
    return 1;
}

static int64_t dos_to_time(uint32_t dostime, uint32_t dosdate) {
    if (dostime == 0 && dosdate == 0)
        return (int64_t)time(NULL);
    struct tm tmv;
    memset(&tmv, 0, sizeof(tmv));
    tmv.tm_year = (int)((dosdate >> 9) & 0x7F) + 80;
    tmv.tm_mon = (int)((dosdate >> 5) & 0xF) - 1;
    tmv.tm_mday = (int)(dosdate & 0x1F);
    tmv.tm_hour = (int)((dostime >> 11) & 0x1F);
    tmv.tm_min = (int)((dostime >> 5) & 0x3F);
    tmv.tm_sec = (int)(dostime & 0x1F) * 2;
    tmv.tm_isdst = -1;
    return (int64_t)mktime(&tmv);
}

static int parse_zip_header(Reader *r, Head *h, int subsequent) {
    unsigned char hdr[26];
    if (rread_exact(r, hdr, 26) != 26) return hdr_fail_unrec(subsequent);
    unsigned flag = get16le(hdr + 2);
    unsigned method = get16le(hdr + 4);
    if (flag & ~0x080F) return hdr_fail_unrec(subsequent);
    uint32_t dostime = get16le(hdr + 6);
    uint32_t dosdate = get16le(hdr + 8);
    uint32_t crc = get32le(hdr + 10);
    uint32_t comp32 = get32le(hdr + 14);
    uint32_t uncomp32 = get32le(hdr + 18);
    unsigned name_len = get16le(hdr + 22);
    unsigned extra_len = get16le(hdr + 24);
    char *name = xmalloc((size_t)name_len + 1);
    if (name_len && rread_exact(r, (unsigned char *)name, name_len) != name_len) { free(name); return hdr_fail_unrec(subsequent); }
    name[name_len] = 0;
    unsigned char *extra = xmalloc(extra_len ? extra_len : 1);
    if (extra_len && rread_exact(r, extra, extra_len) != extra_len) { free(name); free(extra); return hdr_fail_unrec(subsequent); }

    h->form = FORM_ZIP;
    h->method_actual = (int)method;
    h->method = (flag & 1) ? 256 : (int)method;
    h->check = crc;
    h->descriptor = (flag & 8) != 0;
    uint64_t comp = comp32, uncomp = uncomp32;
    int64_t ut_time = 0;
    int have_ut = 0;
    size_t off = 0;
    while (off + 4 <= extra_len) {
        unsigned id = get16le(extra + off);
        unsigned sz = get16le(extra + off + 2);
        if (off + 4 + sz > extra_len) break;
        const unsigned char *pl = extra + off + 4;
        if (id == 0x0001) {
            h->zip64_extra = 1;
            size_t idx = 0;
            if (uncomp32 == 0xFFFFFFFFUL && idx + 8 <= sz) { uncomp = get64le(pl + idx); idx += 8; }
            if (comp32 == 0xFFFFFFFFUL && idx + 8 <= sz) { comp = get64le(pl + idx); idx += 8; }
        } else if (id == 0x5455) {
            if (sz >= 5 && (pl[0] & 1)) {
                ut_time = (int64_t)(int32_t)get32le(pl + 1);
                have_ut = 1;
            }
        }
        off += 4 + sz;
    }
    free(extra);
    h->in_len = comp;
    h->out_len = uncomp;
    h->time = have_ut ? ut_time : dos_to_time(dostime, dosdate);
    h->name = name;
    h->name_present = 1;
    if ((h->method != 8) && subsequent) return 0;
    return 1;
}

/* Parse one header. `subsequent` != 0 selects the silent multi-member mode.
   Returns 1 on header, 0 on no header (subsequent semantics / EOF). */
static int parse_header(Reader *r, Head *h, int subsequent) {
    memset(h, 0, sizeof(*h));
    int first = rgetc2(r);
    if (first < 0) {
        if (subsequent) return 0;
        throw_skip("%s empty", g_in_display);
    }
    if (first == 0x1F) {
        int second = rgetc2(r);
        if (second == 0x8B) {
            return parse_gzip_header(r, h, subsequent);
        } else if (second == 0x9D) {
            if (subsequent) return 0;
            h->form = FORM_LZW;
            h->method = 0; h->method_actual = 0;
            h->time = 0;
            return 1;
        }
        return hdr_fail_unrec(subsequent);
    }
    if (first == 'P') {
        int c2 = rgetc2(r), c3 = rgetc2(r), c4 = rgetc2(r);
        if (c2 == 'K' && c3 == 3 && c4 == 4)
            return parse_zip_header(r, h, subsequent);
        return hdr_fail_unrec(subsequent);
    }
    /* Try zlib. */
    {
        int second = rgetc2(r);
        if (second < 0) return hdr_fail_unrec(subsequent);
        unsigned cmf = (unsigned)first, flg = (unsigned)second;
        if ((((cmf << 8) + flg) % 31 == 0) && ((cmf & 0xF) == 8) && ((cmf >> 4) <= 7) && !(flg & 0x20)) {
            h->form = FORM_ZLIB;
            h->method = 8; h->method_actual = 8;
            h->time = 0;
            return 1;
        }
        return hdr_fail_unrec(subsequent);
    }
}

/* ---------- list ---------- */
static char *list_display_name(Head *h, const char *inpath, int is_stdin) {
    if (h->name_present && h->name != NULL)
        return xstrdup(h->name);
    if (is_stdin)
        return xstrdup("<stdin>");
    char *stripped = strip_suffix(inpath);
    if (stripped) return stripped;
    return xstrdup(inpath);
}

static void format_timestamp(int64_t t, char *buf, size_t bufsz) {
    if (t == 0) {
        snprintf(buf, bufsz, "------ -----");
        return;
    }
    time_t tt = (time_t)t;
    struct tm tmv, nowtm;
    localtime_r(&tt, &tmv);
    time_t now = time(NULL);
    localtime_r(&now, &nowtm);
    if (tmv.tm_year == nowtm.tm_year)
        strftime(buf, bufsz, "%b %e %H:%M", &tmv);
    else
        strftime(buf, bufsz, "%b %e  %Y", &tmv);
}

static void do_list(Reader *r, Head *h, const char *inpath, int is_stdin) {
    uint64_t comp = 0, orig = 0;
    uint32_t check = 0;
    int check_known = 1;
    int explicit_unknown = 0;
    const char *formname = "gzip";
    char methodstr[32];
    char checkstr[32];
    if (h->form == FORM_GZIP) {
        formname = "gzip";
        snprintf(methodstr, sizeof(methodstr), "%d", h->method);
        /* Read all the rest, remembering the last 8 bytes. */
        unsigned char last[8] = {0};
        size_t lastn = 0;
        uint64_t rest = 0;
        unsigned char buf[65536];
        size_t n;
        while ((n = rread(r, buf, sizeof(buf))) > 0) {
            rest += n;
            if (n >= 8) {
                memcpy(last, buf + n - 8, 8); lastn = 8;
            } else {
                if (lastn + n > 8) {
                    size_t drop = (lastn + n) - 8;
                    memmove(last, last + drop, lastn - drop);
                    lastn -= drop;
                }
                memcpy(last + lastn, buf, n); lastn += n;
            }
        }
        if (rest < 10)
            throw_skip("%s not a valid gzip file", g_in_display);
        comp = rest - 8;
        check = get32le(last);
        orig = get32le(last + 4);
    } else if (h->form == FORM_ZLIB) {
        formname = "zlib";
        snprintf(methodstr, sizeof(methodstr), "%d", h->method);
        uint32_t roll = 0;
        uint64_t rest = 0;
        unsigned char buf[65536]; size_t n;
        while ((n = rread(r, buf, sizeof(buf))) > 0) {
            rest += n;
            for (size_t i = 0; i < n; i++) roll = (roll << 8) | buf[i];
        }
        comp = (uint64_t)(rest - 4);   /* unsigned wrap matches the original */
        check = roll;
        orig = 0;
    } else if (h->form == FORM_ZIP) {
        formname = "zip";
        snprintf(methodstr, sizeof(methodstr), "%d", h->method);
        comp = h->in_len;
        orig = h->out_len;
        check = h->check;
        if (h->descriptor) { check_known = 0; explicit_unknown = 1; }
    } else { /* LZW */
        formname = "lzw";
        methodstr[0] = 0;
        check_known = 0;
        uint64_t rest = 0;
        unsigned char buf[65536]; size_t n;
        while ((n = rread(r, buf, sizeof(buf))) > 0) rest += n;
        /* `rest` includes the flags byte. */
        comp = (uint64_t)(rest - 1);
        orig = 0;
        if (rest == 0 || comp > 3) explicit_unknown = 1;
    }
    if (check_known) snprintf(checkstr, sizeof(checkstr), "%08x", check);
    else snprintf(checkstr, sizeof(checkstr), "--------");

    int unknown = explicit_unknown;
    if (h->form != FORM_LZW) {
        __int128 c = comp, o = orig;
        if (c > o + 12) unknown = 1;
    }
    char *disp = list_display_name(h, inpath, is_stdin);
    if (!list_header_printed) {
        if (verbosity > 1)
            printf("method    check    timestamp    compressed   original reduced  name\n");
        else
            printf("compressed   original reduced  name\n");
        list_header_printed = 1;
    }
    if (verbosity > 1) {
        char ts[64];
        format_timestamp(h->time, ts, sizeof(ts));
        int width = 6 - (int)strlen(formname);
        if (width < 0) width = 0;
        printf("%s%*s  %s  %s  ", formname, width, methodstr, checkstr, ts);
    }
    if (unknown) {
        printf("%10llu %10llu?  unk    %s\n",
               (unsigned long long)comp, (unsigned long long)orig, disp);
    } else {
        double ratio = (1.0 - (double)comp / (double)orig) * 100.0;
        printf("%10llu %10llu  %5.1f%%  %s\n",
               (unsigned long long)comp, (unsigned long long)orig, ratio, disp);
    }
    free(disp);
}
EOF
