import subprocess,os
EXE=os.path.abspath("./executable")
def decode(data,exe=EXE):
 r=subprocess.run([exe,"-dc"],input=data,capture_output=True); return r

class BitWriter:
 def __init__(self): self.bits=[] # list of bits LSB stream per code appended
 def write(self,code,width):
   for i in range(width): self.bits.append((code>>i)&1)
 def align(self,multiple):
   while len(self.bits)%multiple: self.bits.append(0)
 def bytes(self):
   bits=self.bits[:]
   while len(bits)%8: bits.append(0)
   out=bytearray()
   for i in range(0,len(bits),8):
     b=0
     for j,bit in enumerate(bits[i:i+8]): b|=bit<<j
     out.append(b)
   return bytes(out)

# simulate decoder free counter to assign widths for a literal sequence.
# Model choices: free starts F0 (256 nonblock,257 block). first code no add. each subsequent code: before reading it maybe width based on free; after decoding it, dictionary add at free then free++ if free<=maxcode(maxbits)
# Width increase condition models:
#  A: if free > (1<<width)-1: width++ BEFORE reading next code
#  B: if free >= (1<<width)-1? etc brute via threshold offset parameter.

def build(seq, block=False, maxbits=12, align_on_increase=False, threshold_delta=0, group8=False):
    bw=BitWriter(); width=9; free=257 if block else 256
    maxcode=(1<<maxbits)-1
    codes_written=0
    for idx,code in enumerate(seq):
        # width adjustment before code (except perhaps grouped?)
        # compress read codes in groups: if group8, only adjust at group boundaries based on free at boundary
        if group8:
            if codes_written % 8 ==0:
                # adjust while free - delta > limit
                while free + threshold_delta > (1<<width)-1 and width<maxbits:
                    # alignment in bits is already at group boundary (multiple of previous width*8 by construction only if width unchanged in group)
                    width+=1
        else:
            while free + threshold_delta > (1<<width)-1 and width<maxbits:
                if align_on_increase:
                    bw.align(width*8)  # old width group bits
                width+=1
        bw.write(code,width); codes_written+=1
        if idx==0: continue
        if free<=maxcode:
            free+=1
    hdr=b"\x1f\x9d"+bytes([(0x80 if block else 0)|maxbits])
    return hdr+bw.bytes()

seq=[97]*600
expected=b"a"*600
for block in [False,True]:
 for align in [False,True]:
