    int *prefix = xmalloc((size_t)table_size * sizeof(int));
    unsigned char *suffix = xmalloc((size_t)table_size);
    unsigned char *stackbuf = xmalloc((size_t)table_size + 1024);
    for (int i = 0; i < 256; i++) { prefix[i] = -1; suffix[i] = (unsigned char)i; }

