/* Inflate one raw deflate stream. Updates *check_io (crc or adler initialised
   by caller), *in_count (compressed bytes consumed), *out_count. */
static void inflate_one(DecodeCtx *dc, int form, uint32_t *check_io,
                        uint64_t *in_count, uint64_t *out_count) {
    z_stream strm;
    memset(&strm, 0, sizeof(strm));
    int zret = inflateInit2(&strm, -15);
    if (zret == Z_MEM_ERROR) throw_abort(ENOMEM, "out of memory");
    if (zret != Z_OK) throw_abort(EINVAL, "internal compression error");
    unsigned char inbuf[65536];
    unsigned char outbuf[65536];
    strm.avail_in = 0;
    strm.next_in = inbuf;
    *in_count = 0; *out_count = 0;
    for (;;) {
        if (strm.avail_in == 0) {
            size_t n = rread(dc->reader, inbuf, sizeof(inbuf));
            if (n == 0) {
                inflateEnd(&strm);
                throw_skip("%s: corrupted -- incomplete deflate data", g_in_display);
            }
            strm.next_in = inbuf;
            strm.avail_in = (uInt)n;
        }
        strm.next_out = outbuf;
        strm.avail_out = (uInt)sizeof(outbuf);
        uLong before_in = strm.total_in;
        int r = inflate(&strm, Z_NO_FLUSH);
        size_t produced = sizeof(outbuf) - strm.avail_out;
        if (produced) {
            if (form == FORM_ZLIB)
                *check_io = (uint32_t)adler32(*check_io, outbuf, (uInt)produced);
            else
                *check_io = (uint32_t)crc32(*check_io, outbuf, (uInt)produced);
            *out_count += produced;
            out_data(dc, outbuf, produced);
        }
