static int br_bit(BitReader *br) {
    if (br->hold_bits == 0) {
        int c = rgetc2(br->r);
        if (c < 0) return -1;
        br->hold = (unsigned)c;
        br->hold_bits = 8;
    }
    int bit = (int)(br->hold & 1U);
    br->hold >>= 1;
    br->hold_bits--;
    br->bitpos++;
    return bit;
}
/* Skip bits up to the next multiple of `multiple` (relative to segment
   start). Returns 0 if EOF was reached while skipping. */
static int br_align(BitReader *br, uint64_t multiple) {
    while (((br->bitpos - br->segment_start) % multiple) != 0) {
        if (br_bit(br) < 0) return 0;
    }
    br->segment_start = br->bitpos;
    return 1;
}

static void decode_lzw(DecodeCtx *dc) {
    Reader *r = dc->reader;
    int flags = rgetc2(r);
    if (flags < 0)
        throw_skip("%s: lzw premature end", g_in_display);
    if (flags & 0x60)
        throw_skip("%s: unknown lzw flags set", g_in_display);
    int maxbits = flags & 0x1F;
    if (maxbits < 9 || maxbits > 16)
        throw_skip("%s: lzw bits out of range", g_in_display);
    int block_mode = (flags & 0x80) != 0;
    int maxcode = (1 << maxbits) - 1;
    int first_free = block_mode ? 257 : 256;
    const int clear_code = 256;

    int table_size = 1 << 16;
    int *prefix = xmalloc((size_t)table_size * sizeof(int));
    unsigned char *suffix = xmalloc((size_t)table_size);
    unsigned char *stackbuf = xmalloc((size_t)table_size + 1024);
    for (int i = 0; i < 256; i++) { prefix[i] = -1; suffix[i] = (unsigned char)i; }

    BitReader br;
    memset(&br, 0, sizeof(br));
    br.r = r;
    int n_bits = 9;
    int free_ent = first_free;
    int pending_align_width = 0; /* align before next code (after a clear) */

    /* getcode() as a small state machine inlined in the loop below. */
    int oldcode = -1;
    int finchar = 0;
    for (;;) {
        /* --- read one code --- */
        int code = -1;
        int eof_clean = 0;
        for (;;) {
            if (pending_align_width) {
                int aw = pending_align_width;
                pending_align_width = 0;
                if (!br_align(&br, (uint64_t)aw * 8)) { eof_clean = 1; break; }
            }
            while (free_ent > (1 << n_bits) - 1 && n_bits < maxbits) {
                if (!br_align(&br, (uint64_t)n_bits * 8)) { eof_clean = 1; break; }
                n_bits++;
            }
            if (eof_clean) break;
            /* Availability of a next code. */
            if (br.hold_bits == 0) {
                if (!reader_has_any(r)) { eof_clean = 1; break; }
            } else {
                if (!reader_has_any(r)) { eof_clean = 1; break; }
            }
            code = 0;
            for (int i = 0; i < n_bits; i++) {
                int bit = br_bit(&br);
                if (bit < 0) {
                    free(prefix); free(suffix); free(stackbuf);
                    throw_skip("%s: lzw premature end", g_in_display);
                }
                code |= bit << i;
            }
            break;
        }
        if (eof_clean) break;

        if (block_mode && code == clear_code) {
            pending_align_width = n_bits;
            n_bits = 9;
            free_ent = first_free;
            oldcode = -1;
            continue;
        }
        if (oldcode == -1) {
            if (code > 255) {
                free(prefix); free(suffix); free(stackbuf);
                throw_skip("%s: invalid lzw code", g_in_display);
            }
            finchar = code;
            unsigned char oc = (unsigned char)code;
            out_data(dc, &oc, 1);
            oldcode = code;
            continue;
        }
        if (code > free_ent) {
            free(prefix); free(suffix); free(stackbuf);
            throw_skip("%s: invalid lzw code", g_in_display);
        }
        int incode = code;
        int stackp = 0;
        int cur = code;
        if (cur == free_ent) {
            stackbuf[stackp++] = (unsigned char)finchar;
            cur = oldcode;
        }
        while (cur > 255) {
            if (cur >= table_size) {
                free(prefix); free(suffix); free(stackbuf);
                throw_skip("%s: invalid lzw code", g_in_display);
            }
            stackbuf[stackp++] = suffix[cur];
            cur = prefix[cur];
            if (cur < 0) {
                free(prefix); free(suffix); free(stackbuf);
                throw_skip("%s: invalid lzw code", g_in_display);
            }
        }
        finchar = suffix[cur];
        stackbuf[stackp++] = (unsigned char)finchar;
        /* Output in reverse. */
        {
            int lo = 0, hi = stackp - 1;
            while (lo < hi) {
                unsigned char t = stackbuf[lo]; stackbuf[lo] = stackbuf[hi]; stackbuf[hi] = t; lo++; hi--;
            }
            out_data(dc, stackbuf, (size_t)stackp);
        }
        if (free_ent <= maxcode) {
            suffix[free_ent] = (unsigned char)finchar;
            prefix[free_ent] = oldcode;
            free_ent++;
        }
        oldcode = incode;
    }
    free(prefix); free(suffix); free(stackbuf);
}

/* Decode all entries of one input. First header is in *head (already parsed).
   Throws EX_SKIP / EX_WARN / EX_ABORT. */
static void decode_all(DecodeCtx *dc, Head *head) {
    Reader *r = dc->reader;
    Head cur = *head;
    /* The first head's name is owned by the caller; take a copy for cur
       bookkeeping of subsequent headers. */
    cur.name = NULL; cur.name_present = 0;
    for (;;) {
        if (cur.form == FORM_LZW) {
            decode_lzw(dc);
            return;
        }
        if (cur.method != 8)
            throw_skip("%s unknown compression method", g_in_display);
        uint32_t check = (cur.form == FORM_ZLIB) ? (uint32_t)adler32(0, Z_NULL, 0)
                                                 : (uint32_t)crc32(0, Z_NULL, 0);
        uint64_t in_count = 0, out_count = 0;
        inflate_one(dc, cur.form, &check, &in_count, &out_count);
        int this_form = cur.form;
        if (this_form == FORM_GZIP) {
            unsigned char tr[8];
            read_trailer_exact(r, tr, 8, 0);
            uint32_t want_crc = get32le(tr);
            uint32_t want_len = get32le(tr + 4);
            if (check != want_crc)
                throw_skip("%s: corrupted -- crc32 mismatch", g_in_display);
            if ((uint32_t)(out_count & 0xFFFFFFFFUL) != want_len)
                throw_skip("%s: corrupted -- length mismatch", g_in_display);
            /* Look for another member. */
            Head next;
            int ok = parse_header(r, &next, 1);
            if (!ok) return;
            head_free_name(&cur);
            cur = next;
            continue;
        } else if (this_form == FORM_ZLIB) {
            unsigned char tr[4];
            read_trailer_exact(r, tr, 4, 0);
            uint32_t want = ((uint32_t)tr[0] << 24) | ((uint32_t)tr[1] << 16) |
                            ((uint32_t)tr[2] << 8) | tr[3];
            if (check != want)
                throw_skip("%s: corrupted -- adler32 mismatch", g_in_display);
            if (reader_has_any(r))
                throw_warn(WARN_ZLIB, "%s: trailing junk was ignored", g_in_display);
            return;
        } else if (this_form == FORM_ZIP) {
            uint64_t want_comp = cur.in_len, want_out = cur.out_len;
            uint32_t want_crc = cur.check;
            if (cur.descriptor) {
                unsigned char first4[4];
                read_trailer_exact(r, first4, 4, 1);
                const unsigned char *crcbytes = first4;
                unsigned char crcbuf[4];
                if (first4[0] == 0x50 && first4[1] == 0x4B && first4[2] == 0x07 && first4[3] == 0x08) {
                    read_trailer_exact(r, crcbuf, 4, 1);
                    crcbytes = crcbuf;
                }
                want_crc = get32le(crcbytes);
                if (cur.zip64_extra) {
                    unsigned char nb[8];
                    read_trailer_exact(r, nb, 8, 1); want_comp = get64le(nb);
                    read_trailer_exact(r, nb, 8, 1); want_out = get64le(nb);
                } else {
                    unsigned char nb[4];
                    read_trailer_exact(r, nb, 4, 1); want_comp = get32le(nb);
                    read_trailer_exact(r, nb, 4, 1); want_out = get32le(nb);
                }
            }
            if (check != want_crc)
                throw_skip("%s: corrupted entry -- crc32 mismatch", g_in_display);
            if (in_count != want_comp || out_count != want_out)
                throw_skip("%s: corrupted entry -- length mismatch", g_in_display);
            /* Another local entry right here? */
            {
                unsigned char pk[4];
                size_t got = 0;
                while (got < 4) {
                    int c = rgetc2(r);
                    if (c < 0) break;
                    pk[got++] = (unsigned char)c;
                }
                if (got == 4 && pk[0] == 0x50 && pk[1] == 0x4B && pk[2] == 0x03 && pk[3] == 0x04)
                    throw_warn(WARN_ZIP, "%s: entries after the first were ignored", g_in_display);
            }
            return;
        }
        return;
    }
}
