/* ---------- per-file processing ---------- */
static int ask_overwrite(const char *outname) {
    if (verbosity == 0 || !isatty(STDIN_FILENO)) return 0;
    fprintf(stderr, "%s exists -- overwrite (y/n)? ", outname);
    fflush(stderr);
    char buf[4096];
    if (fgets(buf, sizeof(buf), stdin) == NULL) return 0;
    char *p = buf;
    while (*p == ' ' || *p == '\t') p++;
    return *p == 'y' || *p == 'Y';
}

typedef struct {
    char *path;          /* NULL for stdin */
    int is_stdin;
    const char *in_display;
    char *out_path;
    const char *out_display;
    int in_fd;
    int out_fd;
    int out_is_stdout;
    int out_created;
    struct stat in_stat;
    int have_in_stat;
    Reader reader;
    Writer writer;
    Head head;
    int head_valid;
    int verbose_active;
} FileCtx;

static void apply_metadata(FileCtx *ctx) {
    if (ctx->out_is_stdout || !ctx->out_created) return;
    if (!ctx->have_in_stat) return;
    /* Ownership (best effort), then mode (setuid/setgid masked off), times. */
    (void)fchown(ctx->out_fd, ctx->in_stat.st_uid, ctx->in_stat.st_gid);
    (void)fchmod(ctx->out_fd, (mode_t)(ctx->in_stat.st_mode & 01777));
    struct timespec times[2];
    if (decode_mode != 0 && head_time_flag && ctx->head_valid && ctx->head.time != 0) {
        times[0].tv_sec = (time_t)ctx->head.time; times[0].tv_nsec = 0;
        times[1].tv_sec = (time_t)ctx->head.time; times[1].tv_nsec = 0;
    } else {
        times[0].tv_sec = ctx->in_stat.st_atime; times[0].tv_nsec = 0;
        times[1].tv_sec = ctx->in_stat.st_mtime; times[1].tv_nsec = 0;
    }
    (void)futimens(ctx->out_fd, times);
}

static void close_output(FileCtx *ctx) {
    if (ctx->out_created) {
        if (sync_opt) (void)fsync(ctx->out_fd);
        if (close(ctx->out_fd) != 0) {
            int e = errno;
            ctx->out_created = 1; /* still unlink in the abort cleanup */
            throw_abort(e, "write error on %s (%s)", ctx->out_display, strerror(e));
        }
        ctx->out_fd = -1;
    }
}

/* Open the output (named file or stdout). ctx->out_path is set when named. */
static void open_output(FileCtx *ctx, int is_compress) {
    if (ctx->out_is_stdout) {
        if (is_compress && !force_opt && isatty(STDOUT_FILENO))
            throw_abort(EINVAL, "trying to write compressed data to a terminal (use -f to force)");
        ctx->out_fd = STDOUT_FILENO;
        writer_init(&ctx->writer, ctx->out_fd, ctx->out_display);
        return;
    }
    struct stat st;
    if (lstat(ctx->out_path, &st) == 0 && !force_opt) {
        if (!ask_overwrite(ctx->out_path))
            throw_skip("%s exists", ctx->out_path);
    }
    int fd = open(ctx->out_path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fd < 0) {
        int e = errno;
        throw_abort(e, "write error on %s (%s)", ctx->out_path, strerror(e));
    }
    ctx->out_fd = fd;
    ctx->out_created = 1;
    writer_init(&ctx->writer, fd, ctx->out_display);
}

static void verbose_prefix(FileCtx *ctx) {
    if (verbosity > 1 && decode_mode != 2) {
        fprintf(stderr, "%s to %s ", ctx->in_display, ctx->out_display);
        fflush(stderr);
        ctx->verbose_active = 1;
    }
}
static void verbose_newline(FileCtx *ctx) {
    if (ctx->verbose_active) {
        fputc('\n', stderr);
        fflush(stderr);
        ctx->verbose_active = 0;
    }
}

static void maybe_unlink_input(FileCtx *ctx) {
    if (ctx->is_stdin || keep_input || to_stdout || decode_mode == 2 || list_mode)
        return;
    if (ctx->have_in_stat && ctx->in_stat.st_nlink > 1 && !force_opt) {
        retcode = 1;
        if (verbosity > 0)
            fprintf(stderr, "%s: %s has hard links -- not unlinking\n", prog, ctx->path);
        return;
    }
    unlink(ctx->path);
}

/* Process one non-directory source. Pre-checks (existence, symlink,
   special suffix, ...) are done by the caller / early in this function. */
static void process_one(char *path, int is_stdin) {
    FileCtx *ctx = xmalloc(sizeof(FileCtx));
    memset(ctx, 0, sizeof(*ctx));
    ctx->path = path;
    ctx->is_stdin = is_stdin;
    ctx->in_display = is_stdin ? "<stdin>" : path;
    ctx->in_fd = -1; ctx->out_fd = -1;
    g_in_display = ctx->in_display;

    jmp_buf file_jmp;
    jmp_buf *prev_jmp = cur_jmp;
    if (setjmp(file_jmp)) {
        int kind = exc_state.kind;
        int code = exc_state.code;
        int warn = exc_state.warn;
        char *msg = exc_state.msg; exc_state.msg = NULL;
        cur_jmp = prev_jmp;
        if (kind == EX_SKIP) {
            if (ctx->out_created) {
                close(ctx->out_fd);
                unlink(ctx->out_path);
                ctx->out_created = 0;
            }
            retcode = 1;
            if (verbosity > 0)
                fprintf(stderr, "%s: skipping: %s\n", prog, msg);
            if (ctx->verbose_active) { fputc('\n', stderr); ctx->verbose_active = 0; }
            free(msg);
            reader_free(&ctx->reader);
            head_free_name(&ctx->head);
            if (ctx->in_fd >= 0 && !ctx->is_stdin) close(ctx->in_fd);
            free(ctx->out_path);
            free(ctx);
            return;
        } else if (kind == EX_WARN) {
            /* The decoded data is kept. */
            if (ctx->out_created) {
                apply_metadata(ctx);
                if (sync_opt) (void)fsync(ctx->out_fd);
                close(ctx->out_fd);
                ctx->out_fd = -1;
            }
            retcode = 1;
            if (verbosity > 0)
                fprintf(stderr, "%s: warning: %s\n", prog, msg);
            if (ctx->verbose_active) { fputc('\n', stderr); ctx->verbose_active = 0; }
            free(msg);
            if (warn == WARN_ZLIB)
                maybe_unlink_input(ctx);
            reader_free(&ctx->reader);
            head_free_name(&ctx->head);
            if (ctx->in_fd >= 0 && !ctx->is_stdin) close(ctx->in_fd);
            free(ctx->out_path);
            free(ctx);
            return;
        } else {
            if (ctx->out_created) {
                close(ctx->out_fd);
                unlink(ctx->out_path);
                ctx->out_created = 0;
            }
            exc_state.kind = EX_ABORT;
            exc_state.code = code;
            exc_state.msg = msg;
            reader_free(&ctx->reader);
            head_free_name(&ctx->head);
            if (ctx->in_fd >= 0 && !ctx->is_stdin) close(ctx->in_fd);
            free(ctx->out_path);
            free(ctx);
            longjmp(*prev_jmp, 1);
        }
    }
    cur_jmp = &file_jmp;

    int is_compress = (decode_mode == 0 && !list_mode);

    /* --- determine tentative output name / early suffix checks --- */
    if (!is_stdin && is_compress) {
        if (!force_opt && ends_with_str(path, suffix_opt)) {
            /* Not an error: message only. */
            cur_jmp = prev_jmp;
            complain_skip_noret("%s ends with %s", path, suffix_opt);
            free(ctx);
            return;
        }
    }
    char *tentative_out = NULL;
    if (!is_stdin && !list_mode && decode_mode == 1 && !to_stdout) {
        tentative_out = strip_suffix(path);
        if (tentative_out == NULL) {
            cur_jmp = prev_jmp;
            retcode = 1;
            if (verbosity > 0)
                fprintf(stderr, "%s: skipping: %s does not have compressed suffix\n", prog, path);
            free(ctx);
            return;
        }
    }

    /* --- open input --- */
    if (is_stdin) {
        ctx->in_fd = STDIN_FILENO;
        if (fstat(ctx->in_fd, &ctx->in_stat) == 0) ctx->have_in_stat = 1;
    } else {
        ctx->in_fd = open(path, O_RDONLY);
        if (ctx->in_fd < 0) {
            int e = errno;
            throw_abort(e, "read error on %s (%s)", path, strerror(e));
        }
        if (fstat(ctx->in_fd, &ctx->in_stat) == 0) ctx->have_in_stat = 1;
    }
    reader_init(&ctx->reader, ctx->in_fd, ctx->in_display);

    if (is_compress) {
        /* Output. */
        if (is_stdin || to_stdout) {
            ctx->out_is_stdout = 1;
            ctx->out_display = "<stdout>";
        } else {
            size_t n = strlen(path) + strlen(suffix_opt) + 1;
            ctx->out_path = xmalloc(n);
            snprintf(ctx->out_path, n, "%s%s", path, suffix_opt);
            ctx->out_display = ctx->out_path;
        }
        open_output(ctx, 1);
        verbose_prefix(ctx);
        /* Stored name / stamp. */
        const char *stored_name = NULL;
        int has_name = 0;
        uint32_t stamp_u32 = 0;
        int stamp_nonzero = 0;
        time_t stamp = 0;
        if (ctx->have_in_stat) {
            if (is_stdin) {
                if (S_ISREG(ctx->in_stat.st_mode)) stamp = ctx->in_stat.st_mtime;
            } else {
                stamp = ctx->in_stat.st_mtime;
            }
        }
        stamp_u32 = (uint32_t)stamp;
        stamp_nonzero = (stamp != 0);
        if (!is_stdin && head_name_flag) {
            stored_name = base_name_of(path);
            has_name = 1;
        }
        compress_data(&ctx->reader, &ctx->writer, stored_name, has_name,
                      stamp_u32, stamp_nonzero);
        if (ctx->out_created) {
            apply_metadata(ctx);
            close_output(ctx);
        }
        verbose_newline(ctx);
        maybe_unlink_input(ctx);
    } else {
        /* Decompress / test / list. */
        Head *head = &ctx->head;
        if (!parse_header(&ctx->reader, head, 0)) {
            /* parse_header throws for first headers; keep compiler happy */
            throw_skip("%s unrecognized format", ctx->in_display);
        }
        ctx->head_valid = 1;
        if (list_mode) {
            do_list(&ctx->reader, head, is_stdin ? NULL : path, is_stdin);
            /* done */
        } else {
            if (head->form != FORM_LZW && head->method != 8)
                throw_skip("%s unknown compression method", ctx->in_display);
            DecodeCtx dc;
            dc.reader = &ctx->reader;
            dc.test_only = (decode_mode == 2);
            if (decode_mode == 2) {
                dc.writer = NULL;
                decode_all(&dc, head);
            } else {
                if (is_stdin || to_stdout) {
                    ctx->out_is_stdout = 1;
                    ctx->out_display = "<stdout>";
                } else {
                    char *outp = tentative_out; tentative_out = NULL;
                    if (head_name_flag && head->name_present) {
                        const char *base = base_name_of(head->name);
                        const char *sl = strrchr(path, '/');
                        size_t prelen = sl ? (size_t)(sl + 1 - path) : 0;
                        char *np = xmalloc(prelen + strlen(base) + 1);
                        memcpy(np, path, prelen);
                        strcpy(np + prelen, base);
                        free(outp);
                        outp = np;
                    }
                    ctx->out_path = outp;
                    ctx->out_display = ctx->out_path;
                }
                open_output(ctx, 0);
                dc.writer = &ctx->writer;
                verbose_prefix(ctx);
                decode_all(&dc, head);
                if (ctx->out_created) {
                    apply_metadata(ctx);
                    close_output(ctx);
                }
                verbose_newline(ctx);
                maybe_unlink_input(ctx);
            }
        }
        free(tentative_out);
    }

    cur_jmp = prev_jmp;
    reader_free(&ctx->reader);
    head_free_name(&ctx->head);
    if (ctx->in_fd >= 0 && !ctx->is_stdin) close(ctx->in_fd);
    free(ctx->out_path);
    free(ctx);
}

static void process_path(char *path);

static void process_dir(char *path) {
    DIR *d = opendir(path);
    if (d == NULL) return;
    char **names = NULL;
    int n = 0, cap = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
        if (n == cap) { cap = cap ? cap * 2 : 16; names = xrealloc(names, (size_t)cap * sizeof(char *)); }
        names[n++] = xstrdup(de->d_name);
    }
    closedir(d);
    size_t plen = strlen(path);
    int trailing = (plen > 0 && path[plen - 1] == '/');
    for (int i = 0; i < n; i++) {
        size_t need = plen + strlen(names[i]) + 2;
        char *child = xmalloc(need);
        if (trailing) snprintf(child, need, "%s%s", path, names[i]);
        else snprintf(child, need, "%s/%s", path, names[i]);
        process_path(child);
        free(child);
        free(names[i]);
    }
    free(names);
}

static void process_path(char *path) {
    if (path == NULL) {
        process_one(NULL, 1);
        return;
    }
    struct stat lst;
    if (lstat(path, &lst) != 0) {
        retcode = 1;
        if (verbosity > 0)
            fprintf(stderr, "%s: skipping: %s does not exist\n", prog, path);
        return;
    }
    if (S_ISLNK(lst.st_mode) && !force_opt) {
        retcode = 1;
        if (verbosity > 0)
            fprintf(stderr, "%s: skipping: %s is a symbolic link\n", prog, path);
        return;
    }
    if (S_ISDIR(lst.st_mode)) {
        if (recurse_opt) {
            process_dir(path);
        } else {
            retcode = 1;
            if (verbosity > 0)
                fprintf(stderr, "%s: skipping: %s is a directory\n", prog, path);
        }
        return;
    }
    if (!S_ISREG(lst.st_mode) && !S_ISFIFO(lst.st_mode) && !S_ISLNK(lst.st_mode)) {
        retcode = 1;
        if (verbosity > 0)
            fprintf(stderr, "%s: skipping: %s is a special file or device\n", prog, path);
        return;
    }
    process_one(path, 0);
}
