        }
        stamp_u32 = (uint32_t)stamp;
        stamp_nonzero = (stamp != 0);
        if (!is_stdin && head_name_flag) {
            stored_name = base_name_of(path);
            has_name = 1;
        }
        compress_data(&ctx->reader, &ctx->writer, stored_name, has_name,
                      stamp_u32, stamp_nonzero);
        if (ctx->out_created) {
            apply_metadata(ctx);
            close_output(ctx);
        }
        verbose_newline(ctx);
        maybe_unlink_input(ctx);
    } else {
        /* Decompress / test / list. */
        Head *head = &ctx->head;
        if (!parse_header(&ctx->reader, head, 0)) {
            /* parse_header throws for first headers; keep compiler happy */
            throw_skip("%s unrecognized format", ctx->in_display);
        }
        ctx->head_valid = 1;
        if (list_mode) {
            do_list(&ctx->reader, head, is_stdin ? NULL : path, is_stdin);
            /* done */
        } else {
            if (head->form != FORM_LZW && head->method != 8)
                throw_skip("%s unknown compression method", ctx->in_display);
            DecodeCtx dc;
            dc.reader = &ctx->reader;
            dc.test_only = (decode_mode == 2);
            if (decode_mode == 2) {
                dc.writer = NULL;
                decode_all(&dc, head);
            } else {
                if (is_stdin || to_stdout) {
                    ctx->out_is_stdout = 1;
                    ctx->out_display = "<stdout>";
                } else {
                    char *outp = tentative_out; tentative_out = NULL;
                    if (head_name_flag && head->name_present) {
                        const char *base = base_name_of(head->name);
                        const char *sl = strrchr(path, '/');
                        size_t prelen = sl ? (size_t)(sl + 1 - path) : 0;
                        char *np = xmalloc(prelen + strlen(base) + 1);
                        memcpy(np, path, prelen);
                        strcpy(np + prelen, base);
                        free(outp);
                        outp = np;
                    }
                    ctx->out_path = outp;
                    ctx->out_display = ctx->out_path;
