        if (verbosity > 0 && exc_state.msg)
            fprintf(stderr, "%s: abort: %s\n", prog, exc_state.msg);
        return code != 0 ? code : 1;
    }
    cur_jmp = &main_jmp;

    process_env_var("GZIP");
    process_env_var("PIGZ");

    /* Command line. Build a token source over argv[1..]. */
    TokSrc src;
    src.tokens = argv + 1;
    src.count = argc > 0 ? argc - 1 : 0;
    src.idx = 0;
    src.is_env = 0;
    src.env_name = NULL;
    int end_options = 0;
    while (src.idx < src.count) {
        char *token = src.tokens[src.idx++];
        if (!end_options && strcmp(token, "--") == 0) {
            end_options = 1;
            continue;
        }
        if (!end_options && token[0] == '-' && token[1] != '\0') {
            process_option_token(&src, token);
        } else if (!end_options && strcmp(token, "-") == 0) {
            add_source(NULL);
        } else {
            add_source(token);
        }
    }

    /* Defaults for name/time depending on the final mode. */
    int decoding = (decode_mode != 0 || list_mode);
    if (!head_name_set) head_name_flag = decoding ? 0 : 1;
    if (!head_time_set) head_time_flag = decoding ? 0 : 1;

    if (nsources == 0) {
        /* "pigz" with no command-line arguments and a terminal stdout
           shows the help screen when it would compress. */
        if (orig_argc == 1 && decode_mode == 0 && !list_mode && isatty(STDOUT_FILENO)) {
            if (verbosity > 0) {
                fputs(help_text, stderr);
                return 0;
            }
        }
        add_source(NULL);
    }

    for (int i = 0; i < nsources; i++)
        process_path(sources[i].path);

    return retcode;
}
