static unsigned char *in_data; static size_t in_len, in_pos;
static unsigned in_cb(void *desc, z_const unsigned char **buf) {
    (void)desc;
    if (in_pos >= in_len) return 0;
    *buf = in_data + in_pos;
    unsigned n = (unsigned)(in_len - in_pos);
    in_pos = in_len;
    return n;
}
static int out_cb(void *desc, unsigned char *buf, unsigned len) {
    (void)desc; fwrite(buf,1,len,stdout); return 0;
}
int main(void){
    // read stdin all (raw deflate only input)
    size_t cap=1<<20; in_data=malloc(cap); in_len=fread(in_data,1,cap,stdin);
    unsigned char *window=calloc(32768,1);
    z_stream strm; memset(&strm,0,sizeof(strm));
    int r=inflateBackInit(&strm,15,window);
    fprintf(stderr,"init=%d\n",r);
    strm.next_in=Z_NULL; strm.avail_in=0;
    r=inflateBack(&strm,in_cb,NULL,out_cb,NULL);
    fprintf(stderr,"\nret=%d msg=%s total_in=%lu total_out=%lu avail_in=%u\n",r,strm.msg?strm.msg:"(null)",strm.total_in,strm.total_out,strm.avail_in);
    inflateBackEnd(&strm);
