{"command":"cat > /tmp/edit_back.py << 'PY'
import pathlib
p=pathlib.Path("pigz.c"); s=p.read_text()
start=s.index("/* Inflate one raw deflate stream.")
end=s.index("static void read_trailer_exact",start)
new = r'''/* Inflate one raw deflate stream with inflateBack() (as pigz does), using a
   process-global 32 KiB window that starts zeroed and is retained across
   streams and files. Updates the check value and the byte counts. */
typedef struct {
    DecodeCtx *dc;
    int form;
    uint32_t check;
    uint64_t supplied;
    uint64_t out_count;
    unsigned char inbuf[65536];
} BackIO;

static unsigned back_in(void *desc, z_const unsigned char **buf) {
    BackIO *bio = (BackIO *)desc;
    size_t n = rread(bio->dc->reader, bio->inbuf, sizeof(bio->inbuf));
    *buf = bio->inbuf;
    bio->supplied += n;
    return (unsigned)n;
}
static int back_out(void *desc, unsigned char *buf, unsigned len) {
    BackIO *bio = (BackIO *)desc;
    if (len) {
        if (bio->form == FORM_ZLIB)
            bio->check = (uint32_t)adler32(bio->check, buf, len);
        else
            bio->check = (uint32_t)crc32(bio->check, buf, len);
        bio->out_count += len;
        if (!bio->dc->test_only)
            write_all(bio->dc->writer, buf, len);
    }
    return 0;
}

static unsigned char *back_window = NULL;

static void inflate_one(DecodeCtx *dc, int form, uint32_t *check_io,
                        uint64_t *in_count, uint64_t *out_count) {
    if (back_window == NULL) {
        back_window = calloc(32768, 1);
        if (back_window == NULL) throw_abort(ENOMEM, "out of memory");
    }
    BackIO *bio = xmalloc(sizeof(BackIO));
    memset(bio, 0, sizeof(*bio));
    bio->dc = dc;
    bio->form = form;
    bio->check = *check_io;
    z_stream strm;
    memset(&strm, 0, sizeof(strm));
    int zret = inflateBackInit(&strm, 15, back_window);
    if (zret == Z_MEM_ERROR) { free(bio); throw_abort(ENOMEM, "out of memory"); }
    if (zret != Z_OK) { free(bio); throw_abort(EINVAL, "internal compression error"); }
    strm.next_in = Z_NULL;
    strm.avail_in = 0;
    int r = inflateBack(&strm, back_in, bio, back_out, bio);
    if (r == Z_STREAM_END) {
        *in_count = bio->supplied - strm.avail_in;
