static int pm_cmp_syms(const int *a, int an, const int *b, int bn) {
    int m = an < bn ? an : bn;
    for (int i = 0; i < m; i++) if (a[i] != b[i]) return a[i] - b[i];
    return an - bn;
}
static int pm_cmp(const PMItem *a, const PMItem *b) {
    if (a->w != b->w) return a->w < b->w ? -1 : 1;
    return pm_cmp_syms(a->syms, a->n, b->syms, b->n);
}
static void pm_sort(PMItem *a, int n) {
    for (int i = 1; i < n; i++) {
