        pm_sort(cur, cur_n);
    }
    int take = 2 * k - 2;
    if (take > cur_n) take = cur_n;
    for (int i = 0; i < take; i++)
        for (int j = 0; j < cur[i].n; j++) lengths[cur[i].syms[j]]++;
    for (int i = 0; i < cur_n; i++) if (!cur[i].is_single) free(cur[i].syms);
    free(cur);
    for (int i = 0; i < k; i++) free(items[i].syms);
    free(items); free(syms);
    /* Kraft check, scaled by 2^maxlen. */
    uint64_t kraft = 0;
    for (int i = 0; i < n; i++) {
        if (lengths[i] < 0 || lengths[i] > maxlen) return 0;
        if (lengths[i]) kraft += 1ULL << (maxlen - lengths[i]);
    }
    return kraft <= (1ULL << maxlen);
}
static void make_canonical(const int *lengths, int n, unsigned int *codes) {
    int bl[16] = {0};
    for (int i = 0; i < n; i++) if (lengths[i]) bl[lengths[i]]++;
    unsigned int next[16] = {0};
    unsigned int code = 0;
    for (int b = 1; b < 16; b++) { code = (code + bl[b - 1]) << 1; next[b] = code; }
    for (int i = 0; i < n; i++) codes[i] = lengths[i] ? next[lengths[i]]++ : 0;
}
typedef struct { Buf *out; uint32_t acc; int nbits; uint64_t total; } BitW;
static void bw_bits(BitW *bw, unsigned int value, int n) {
    bw->acc |= value << bw->nbits;
    bw->nbits += n; bw->total += (uint64_t)n;
    while (bw->nbits >= 8) {
        buf_reserve(bw->out, bw->out->len + 1);
        bw->out->data[bw->out->len++] = (unsigned char)(bw->acc & 0xFF);
        bw->acc >>= 8; bw->nbits -= 8;
    }
}
static void bw_code(BitW *bw, unsigned int code, int n) {
    unsigned int rev = 0;
    for (int i = 0; i < n; i++) rev = (rev << 1) | ((code >> i) & 1U);
    bw_bits(bw, rev, n);
}
static void bw_align_byte(BitW *bw) {
    int rem = (int)(bw->total & 7);
    if (rem) bw_bits(bw, 0, 8 - rem);
}
static void bw_stored_empty(BitW *bw) {
    bw_bits(bw, 0, 1); bw_bits(bw, 0, 2); bw_align_byte(bw);
    bw_bits(bw, 0, 8); bw_bits(bw, 0, 8); bw_bits(bw, 0xFF, 8); bw_bits(bw, 0xFF, 8);
}
static void bw_chunk_align(BitW *bw) {
    if (independent_opt) {
        bw_stored_empty(bw);
        static const unsigned char marker[5] = {0,0,0,0xFF,0xFF};
        for (int i = 0; i < 5; i++) bw_bits(bw, marker[i], 8);
        return;
    }
    int rem = (int)(bw->total & 7);
    if (rem == 0) return;
    if (rem & 1) { bw_stored_empty(bw); return; }
    while ((bw->total & 7) != 0) {
        bw_bits(bw, 0, 1); bw_bits(bw, 1, 2); bw_code(bw, 0, 7);
    }
}

typedef struct { int len; int dist; int lit; } Op;

static const int kCLOrder[19] = {16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15};

static int encode_ops(const Op *seq, int nseq, const unsigned char *chunk, size_t chunk_len,
                      int is_last, int dynamic, Buf *out) {
    unsigned int litcounts[286] = {0}, distcounts[30] = {0};
    for (int i = 0; i < nseq; i++) {
        if (seq[i].dist == 0) litcounts[seq[i].lit]++;
        else { litcounts[len_to_sym(seq[i].len)]++; distcounts[dist_to_sym(seq[i].dist)]++; }
    }
    litcounts[256]++;
    int litlen[286], distlen[30];
    if (dynamic) {
        if (!package_merge_lengths(litcounts, 286, 15, litlen)) return 0;
        if (!package_merge_lengths(distcounts, 30, 15, distlen)) return 0;
    } else {
        for (int i = 0; i < 286; i++) litlen[i] = i < 144 ? 8 : i < 256 ? 9 : i < 280 ? 7 : 8;
        for (int i = 0; i < 30; i++) distlen[i] = 5;
    }
    unsigned int litcodes[286], distcodes[30];
    make_canonical(litlen, 286, litcodes);
    make_canonical(distlen, 30, distcodes);
    BitW bw; memset(&bw, 0, sizeof(bw)); bw.out = out;
    bw_bits(&bw, is_last ? 1 : 0, 1);
    if (dynamic) {
        bw_bits(&bw, 2, 2);
        int hlit = 286; while (hlit > 257 && litlen[hlit - 1] == 0) hlit--;
        int hdist = 30; while (hdist > 1 && distlen[hdist - 1] == 0) hdist--;
        int total_cl = hlit + hdist;
        int *clseq_sym = xmalloc((size_t)(total_cl + 16) * sizeof(int));
        int *clseq_ev = xmalloc((size_t)(total_cl + 16) * sizeof(int));
        int *clseq_eb = xmalloc((size_t)(total_cl + 16) * sizeof(int));
        int ncl = 0;
        int *all = xmalloc((size_t)total_cl * sizeof(int));
        memcpy(all, litlen, (size_t)hlit * sizeof(int));
        memcpy(all + hlit, distlen, (size_t)hdist * sizeof(int));
        for (int i = 0; i < total_cl; ) {
            int v = all[i]; int j = i;
            while (j < total_cl && all[j] == v) j++;
            int run = j - i;
            if (v == 0) {
                while (run >= 11) { int take = run > 138 ? 138 : run; clseq_sym[ncl]=18; clseq_ev[ncl]=take-11; clseq_eb[ncl++]=7; run-=take; }
                if (run >= 3) { clseq_sym[ncl]=17; clseq_ev[ncl]=run-3; clseq_eb[ncl++]=3; run=0; }
                while (run-- > 0) { clseq_sym[ncl]=0; clseq_ev[ncl]=0; clseq_eb[ncl++]=0; }
            } else {
                clseq_sym[ncl]=v; clseq_ev[ncl]=0; clseq_eb[ncl++]=0; run--;
                while (run >= 3) { int take = run > 6 ? 6 : run; clseq_sym[ncl]=16; clseq_ev[ncl]=take-3; clseq_eb[ncl++]=2; run-=take; }
                while (run-- > 0) { clseq_sym[ncl]=v; clseq_ev[ncl]=0; clseq_eb[ncl++]=0; }
            }
            i = j;
        }
        unsigned int clcounts[19] = {0};
        for (int i = 0; i < ncl; i++) clcounts[clseq_sym[i]]++;
        int cllen[19];
        if (!package_merge_lengths(clcounts, 19, 7, cllen)) { free(clseq_sym); free(clseq_ev); free(clseq_eb); free(all); return 0; }
        unsigned int clcodes[19]; make_canonical(cllen, 19, clcodes);
        int hclen = 19; while (hclen > 4 && cllen[kCLOrder[hclen - 1]] == 0) hclen--;
        bw_bits(&bw, (unsigned)(hlit - 257), 5);
        bw_bits(&bw, (unsigned)(hdist - 1), 5);
        bw_bits(&bw, (unsigned)(hclen - 4), 4);
        for (int i = 0; i < hclen; i++) bw_bits(&bw, (unsigned)cllen[kCLOrder[i]], 3);
        for (int i = 0; i < ncl; i++) {
            bw_code(&bw, clcodes[clseq_sym[i]], cllen[clseq_sym[i]]);
            if (clseq_eb[i]) bw_bits(&bw, (unsigned)clseq_ev[i], clseq_eb[i]);
        }
        free(clseq_sym); free(clseq_ev); free(clseq_eb); free(all);
    } else {
        bw_bits(&bw, 1, 2);
    }
    for (int i = 0; i < nseq; i++) {
        if (seq[i].dist == 0) {
            bw_code(&bw, litcodes[seq[i].lit], litlen[seq[i].lit]);
        } else {
            int lsym = len_to_sym(seq[i].len);
            bw_code(&bw, litcodes[lsym], litlen[lsym]);
            int lb = lsym - 257;
            if (kLengthExtra[lb]) bw_bits(&bw, (unsigned)(seq[i].len - kLengthBase[lb]), kLengthExtra[lb]);
            int dsym = dist_to_sym(seq[i].dist);
            bw_code(&bw, distcodes[dsym], distlen[dsym]);
            if (kDistExtra[dsym]) bw_bits(&bw, (unsigned)(seq[i].dist - kDistBase[dsym]), kDistExtra[dsym]);
        }
    }
    bw_code(&bw, litcodes[256], litlen[256]);
    if (is_last) bw_align_byte(&bw); else bw_chunk_align(&bw);
    (void)chunk; (void)chunk_len;
    return 1;
}

static int encode_stored11(const unsigned char *chunk, size_t len, int is_last, Buf *out) {
    BitW bw; memset(&bw, 0, sizeof(bw)); bw.out = out;
    size_t off = 0;
    if (len == 0) {
        bw_bits(&bw, is_last ? 1 : 0, 1); bw_bits(&bw, 0, 2); bw_align_byte(&bw);
        bw_bits(&bw, 0, 8); bw_bits(&bw, 0, 8); bw_bits(&bw, 0xFF, 8); bw_bits(&bw, 0xFF, 8);
        if (!is_last && independent_opt) {
            static const unsigned char marker[5] = {0,0,0,0xFF,0xFF};
            for (int i = 0; i < 5; i++) bw_bits(&bw, marker[i], 8);
        }
        return 1;
    }
    while (off < len) {
        size_t take = len - off; if (take > 65535) take = 65535;
        int lastblock = is_last && (off + take == len);
        bw_bits(&bw, lastblock ? 1 : 0, 1); bw_bits(&bw, 0, 2); bw_align_byte(&bw);
        bw_bits(&bw, (unsigned)(take & 0xFF), 8); bw_bits(&bw, (unsigned)((take >> 8) & 0xFF), 8);
        bw_bits(&bw, (unsigned)(~take & 0xFF), 8); bw_bits(&bw, (unsigned)((~take >> 8) & 0xFF), 8);
        for (size_t i = 0; i < take; i++) bw_bits(&bw, chunk[off + i], 8);
        off += take;
    }
    if (!is_last && independent_opt) {
        bw_stored_empty(&bw);
        static const unsigned char marker[5] = {0,0,0,0xFF,0xFF};
        for (int i = 0; i < 5; i++) bw_bits(&bw, marker[i], 8);
    }
    return 1;
}

typedef struct { uint16_t len; uint16_t dist; } MatchOpt;

static int opt_encode_chunk(CompressCtx *cc, const unsigned char *data, size_t len,
                            int is_first, int is_last, Buf *out) {
    size_t dict_len = (!is_first && !independent_opt) ? cc->dict_len : 0;
    size_t total = dict_len + len;
    unsigned char *in = xmalloc(total ? total : 1);
    if (dict_len) memcpy(in, cc->dict, dict_len);
    if (len) memcpy(in + dict_len, data, len);
    int success = 0;
    int *head = NULL, *prev = NULL, *opt_start = NULL, *opt_count = NULL;
    MatchOpt *opts = NULL; size_t opts_len = 0, opts_cap = 0;
    int *costs = NULL, *choice_len = NULL;
    unsigned short *choice_dist = NULL;
    Op *seq = NULL;
    Buf *best = NULL;

    head = xmalloc(65536 * sizeof(int));
    for (int i = 0; i < 65536; i++) head[i] = -1;
    prev = xmalloc((total ? total : 1) * sizeof(int));
    for (size_t i = 0; i < total; i++) {
        prev[i] = -1;
        if (i + 2 < total) {
            unsigned h = ((unsigned)in[i] << 16) ^ ((unsigned)in[i + 1] << 8) ^ in[i + 2];
            h = (h * 2654435761u) >> 16;
            prev[i] = head[h]; head[h] = (int)i;
        }
    }
    opt_start = xmalloc((total ? total : 1) * sizeof(int));
    opt_count = xmalloc((total ? total : 1) * sizeof(int));
    for (size_t pos = dict_len; pos < total; pos++) {
        opt_start[pos] = (int)opts_len; opt_count[pos] = 0;
        size_t maxlen = total - pos; if (maxlen > 258) maxlen = 258;
        if (maxlen < 3) continue;
        int best = 0; int trials = 0;
        int cand = prev[pos];
        while (cand >= 0 && pos - (size_t)cand <= 32768 && trials < 4096) {
            trials++;
            if (best == 0 || in[(size_t)cand + best] == in[pos + best]) {
                size_t l = 0;
                while (l < maxlen && in[(size_t)cand + l] == in[pos + l]) l++;
                if (l > (size_t)best && l >= 3) {
                    if (opts_len == opts_cap) { opts_cap = opts_cap ? opts_cap * 2 : 16384; opts = xrealloc(opts, opts_cap * sizeof(MatchOpt)); }
                    opts[opts_len].len = (uint16_t)l;
                    opts[opts_len].dist = (uint16_t)(pos - (size_t)cand);
                    opts_len++; opt_count[pos]++;
                    best = (int)l;
                    if ((size_t)best >= maxlen) break;
                }
            }
            cand = prev[cand];
        }
    }

    costs = xmalloc((total + 1) * sizeof(int));
    choice_len = xmalloc((total ? total : 1) * sizeof(int));
    choice_dist = xmalloc((total ? total : 1) * sizeof(unsigned short));
    seq = xmalloc((len ? len : 1) * sizeof(Op));
    int litlen[286], distlen[30];
    for (int i = 0; i < 286; i++) litlen[i] = i < 144 ? 8 : i < 256 ? 9 : i < 280 ? 7 : 8;
    for (int i = 0; i < 30; i++) distlen[i] = 5;
    int niter = iterations_opt;
    if (niter > 100) niter = 100;
    if (niter < 1) niter = 1;
    for (int iter = 0; iter < niter; iter++) {
        costs[total] = 0;
        for (size_t rp = total; rp-- > dict_len; ) {
            size_t pos = rp;
            int litc = litlen[in[pos]] ? litlen[in[pos]] : 32;
            int bestcost = litc + costs[pos + 1];
            int blen = 1, bdist = 0;
            int oc = opt_count[pos];
            if (oc) {
                int oi = 0;
                int maxl = opts[opt_start[pos] + oc - 1].len;
                for (int l = 3; l <= maxl; l++) {
                    while (opts[opt_start[pos] + oi].len < l) oi++;
                    int dist = opts[opt_start[pos] + oi].dist;
                    int lsym = len_to_sym(l);
                    int dsym = dist_to_sym(dist);
                    int c = (litlen[lsym] ? litlen[lsym] : 32) + kLengthExtra[lsym - 257] +
                            (distlen[dsym] ? distlen[dsym] : 32) + kDistExtra[dsym] + costs[pos + l];
                    if (c < bestcost) { bestcost = c; blen = l; bdist = dist; }
                }
            }
            costs[pos] = bestcost; choice_len[pos] = blen; choice_dist[pos] = (unsigned short)bdist;
        }
        int nseq = 0;
        for (size_t pos = dict_len; pos < total; ) {
            if (choice_dist[pos] == 0) { seq[nseq].len = 1; seq[nseq].dist = 0; seq[nseq].lit = in[pos]; nseq++; pos++; }
            else { seq[nseq].len = choice_len[pos]; seq[nseq].dist = choice_dist[pos]; seq[nseq].lit = 0; nseq++; pos += (size_t)choice_len[pos]; }
        }
        /* Encode this parse three ways; keep the smallest overall. */
        for (int kind = 0; kind < 3; kind++) {
            Buf *cand = xmalloc(sizeof(Buf)); memset(cand, 0, sizeof(*cand));
            int ok;
            if (kind == 0) ok = encode_ops(seq, nseq, data, len, is_last, 1, cand);
            else if (kind == 1) ok = encode_ops(seq, nseq, data, len, is_last, 0, cand);
            else ok = encode_stored11(data, len, is_last, cand);
            if (ok && cand->len > 0 && (best == NULL || cand->len < best->len)) {
                if (best) { free(best->data); free(best); }
