/* Parallel compression of a batch of chunks. Each job compresses into its
   own memory buffer; the main thread writes them out in order. */
typedef struct {
    Buf in;
    Buf out;
    unsigned char dict[32768];
    size_t dict_len;
    int is_first;
    int is_last;
} CompJob;
typedef struct {
    CompJob *jobs;
    int njobs;
    int next;
    pthread_mutex_t mu;
} CompWork;
static void comp_job_run(CompJob *job) {
    CompressCtx jcc;
    memset(&jcc, 0, sizeof(jcc));
    memcpy(jcc.dict, job->dict, job->dict_len);
    jcc.dict_len = job->dict_len;
    Writer mw;
    memset(&mw, 0, sizeof(mw));
    mw.fd = -1; mw.name = "<mem>"; mw.mem = &job->out;
    jcc.writer = &mw;
    if (level_opt == 11)
        compress_chunk_11(&jcc, job->in.data, job->in.len, job->is_first, job->is_last);
    else
        compress_chunk_zlib(&jcc, job->in.data, job->in.len, job->is_first, job->is_last, level_opt);
}
static void *comp_worker(void *arg) {
    CompWork *work = (CompWork *)arg;
    for (;;) {
        pthread_mutex_lock(&work->mu);
        int idx = work->next++;
        pthread_mutex_unlock(&work->mu);
        if (idx >= work->njobs) break;
        comp_job_run(&work->jobs[idx]);
    }
    return NULL;
}
static void run_jobs_parallel(CompJob *jobs, int njobs, int workers) {
    if (njobs <= 1 || workers <= 1) {
        for (int i = 0; i < njobs; i++) comp_job_run(&jobs[i]);
        return;
    }
    if (workers > njobs) workers = njobs;
    CompWork work;
    work.jobs = jobs; work.njobs = njobs; work.next = 0;
    pthread_mutex_init(&work.mu, NULL);
    pthread_t *threads = xmalloc((size_t)workers * sizeof(pthread_t));
    int started = 0;
    for (int i = 0; i < workers; i++) {
        if (pthread_create(&threads[i], NULL, comp_worker, &work) != 0) break;
        started++;
    }
    if (started == 0) {
        for (int i = 0; i < njobs; i++) comp_job_run(&jobs[i]);
    } else {
        for (int i = 0; i < started; i++) pthread_join(threads[i], NULL);
    }
    free(threads);
    pthread_mutex_destroy(&work.mu);
}

