{"command":"cat > /tmp/fuzz_lzw.py << 'PY'
import subprocess,random,sys
# Use a packer that simulates decoder free/width from lzw_model, extended to arbitrary code sequences including clears in block mode.
# We'll generate code sequences from a simulated encoder table state randomly choosing valid-ish codes.
import math
class BW:
 def __init__(self): self.bits=[]
 def write(self,c,w):
  for i in range(w): self.bits.append((c>>i)&1)
 def pad(self,mult,base):
  while (len(self.bits)-base)%mult: self.bits.append(0)
 def bytes(self):
  bits=self.bits[:]
  while len(bits)%8: bits.append(0)
  return bytes(sum(bit<<j for j,bit in enumerate(bits[i:i+8])) for i in range(0,len(bits),8))

def pack(codes,maxbits=12,block=True):
 bw=BW(); width=9; maxmax=1<<maxbits; maxcode=(1<<9)-1; free=257 if block else 256; group=0; first=True
 for code in codes:
  if block and code==256:
   # If first, write at width9; align semantics in builder for testing decoder differences after start only generate clears later in caller.
   bw.write(code,width); bw.pad(width*8,group); width=9; maxcode=(1<<9)-1; free=257; group=len(bw.bits); first=True; continue
  while free>maxcode:
   bw.pad(width*8,group); width+=1; maxcode=maxmax if width==maxbits else (1<<width)-1; group=len(bw.bits)
  bw.write(code,width)
  if first:first=False
  else:
   if free<maxmax:free+=1
 return b"\x1f\x9d"+bytes([(128 if block else 0)|maxbits])+bw.bytes()

fails=0;total=0; rnd=random.Random(4)
for trial in range(300):
 maxbits=rnd.choice([9,10,12,16]); block=rnd.random()<0.7
 # generate a random valid-ish sequence by simulating decoder free: codes can be literals, dictionary codes <=free, occasional clear/invalid
 codes=[]; free=257 if block else 256; first=True
 for i in range(rnd.randrange(0,200)):
  r=rnd.random()
  if block and not first and r<0.03:
   codes.append(256); free=257; first=True; continue
  if first or rnd.random()<0.6: code=rnd.randrange(256)
  else: code=rnd.randrange(0,free+3)  # sometimes invalid free+1/free+2
  codes.append(code)
  if first:first=False
  else:
   if free<(1<<maxbits):free+=1
 data=pack(codes,maxbits,block)
 # sometimes truncate/mutate
 if rnd.random()<0.3 and len(data)>4: data=data[:rnd.randrange(3,len(data)+1)]
 total+=1
 r1=subprocess.run(["./executable","-dc"],input=data,capture_output=True)
 r2=subprocess.run(["/tmp/newbin/executable","-dc"],input=data,capture_output=True)
 if (r1.returncode,r1.stdout,r1.stderr)!=(r2.returncode,r2.stdout,r2.stderr):
  fails+=1; print("FAIL",trial,maxbits,block,"codes",codes[:30],"data",data.hex()[:200])
  print(" orig",r1.returncode,r1.stdout[:80],r1.stderr[:150]); print(" new",r2.returncode,r2.stdout[:80],r2.stderr[:150])
  if fails>20:break
print(total-fails,total)
