{"command":"cat > /tmp/edit_lzw_group.py << 'PY'
import pathlib
p=pathlib.Path("pigz.c"); s=p.read_text()
start=s.index("/* LZW (.Z) decoding. */")
end=s.index("static void cat_rest",start)
new=r'''/* LZW (.Z) decoding. Codes are read in groups of n_bits bytes (eight
   codes per group), as in the classic compress format. */
typedef struct {
    Reader *r;
    unsigned char buf[16];
    int gbits;
    int goff;
} GroupReader;

/* Return 1 for a code, 0 for a clean end of file, -1 for a premature end. */
static int gr_getcode(GroupReader *gr, int width, int *out_code) {
    if (gr->goff + width > gr->gbits) {
        size_t n = rread(gr->r, gr->buf, (size_t)width);
        if (n == 0) return 0;
        if (n * 8 < (size_t)width) return -1;
        gr->gbits = (int)(n * 8);
        gr->goff = 0;
    }
    int code = 0;
    for (int i = 0; i < width; i++) {
        int bit = (gr->buf[(gr->goff + i) / 8] >> ((gr->goff + i) % 8)) & 1;
        code |= bit << i;
    }
    gr->goff += width;
    *out_code = code;
    return 1;
}

static void decode_lzw(DecodeCtx *dc) {
    Reader *r = dc->reader;
    int flags = rgetc2(r);
    if (flags < 0)
        throw_skip("%s: lzw premature end", g_in_display);
    if (flags & 0x60)
        throw_skip("%s: unknown lzw flags set", g_in_display);
    int maxbits = flags & 0x1F;
    if (maxbits < 9 || maxbits > 16)
        throw_skip("%s: lzw bits out of range", g_in_display);
    int block_mode = (flags & 0x80) != 0;
    int maxmaxcode = 1 << maxbits;
    int maxcode = (1 << 9) - 1;   /* current-width limit, as in the classic decoder */
    int first_free = block_mode ? 257 : 256;
    const int clear_code = 256;

    int table_size = 1 << 16;
    int *prefix = xmalloc((size_t)table_size * sizeof(int));
    unsigned char *suffix = xmalloc((size_t)table_size);
    unsigned char *stackbuf = xmalloc((size_t)table_size + 1024);
    for (int i = 0; i < 256; i++) { prefix[i] = -1; suffix[i] = (unsigned char)i; }

    GroupReader gr;
    memset(&gr, 0, sizeof(gr));
    gr.r = r;
    int n_bits = 9;
    int free_ent = first_free;
    int pending_discard = 0; /* discard the rest of the group (after a clear) */

    int oldcode = -1;
    int finchar = 0;
    int first_ever = 1;
    for (;;) {
        if (pending_discard) {
            gr.goff = gr.gbits;
            pending_discard = 0;
        }
        while (free_ent > maxcode) {
            gr.goff = gr.gbits;
            n_bits++;
            maxcode = (n_bits == maxbits) ? maxmaxcode : ((1 << n_bits) - 1);
        }
        int code = -1;
        int grc = gr_getcode(&gr, n_bits, &code);
        if (grc == 0) break;
        if (grc < 0) {
            free(prefix); free(suffix); free(stackbuf);
            throw_skip("%s: lzw premature end", g_in_display);
        }
        if (block_mode && code == clear_code) {
            if (first_ever) {
                free(prefix); free(suffix); free(stackbuf);
                throw_skip("%s: invalid lzw code", g_in_display);
            }
            pending_discard = 1;
            n_bits = 9;
            maxcode = (1 << 9) - 1;
            free_ent = first_free;
            oldcode = -1;
            continue;
        }
        if (oldcode == -1) {
            if (code > 255) {
                free(prefix); free(suffix); free(stackbuf);
                throw_skip("%s: invalid lzw code", g_in_display);
            }
            finchar = code;
            first_ever = 0;
            unsigned char oc = (unsigned char)code;
            out_data(dc, &oc, 1);
            oldcode = code;
            continue;
        }
        if (code > free_ent) {
            free(prefix); free(suffix); free(stackbuf);
            throw_skip("%s: invalid lzw code", g_in_display);
        }
        int incode = code;
        int stackp = 0;
        int cur = code;
        if (cur == free_ent) {
            stackbuf[stackp++] = (unsigned char)finchar;
            cur = oldcode;
        }
        while (cur > 255) {
            if (cur >= table_size) {
                free(prefix); free(suffix); free(stackbuf);
                throw_skip("%s: invalid lzw code", g_in_display);
            }
            stackbuf[stackp++] = suffix[cur];
            cur = prefix[cur];
            if (cur < 0) {
                free(prefix); free(suffix); free(stackbuf);
                throw_skip("%s: invalid lzw code", g_in_display);
            }
        }
        finchar = suffix[cur];
        stackbuf[stackp++] = (unsigned char)finchar;
        {
            int lo = 0, hi = stackp - 1;
            while (lo < hi) {
                unsigned char t = stackbuf[lo]; stackbuf[lo] = stackbuf[hi]; stackbuf[hi] = t; lo++; hi--;
            }
            out_data(dc, stackbuf, (size_t)stackp);
        }
        if (free_ent < maxmaxcode) {
            suffix[free_ent] = (unsigned char)finchar;
            prefix[free_ent] = oldcode;
            free_ent++;
        }
        oldcode = incode;
    }
    out_flush(dc);
    free(prefix); free(suffix); free(stackbuf);
}

'''
s=s[:start]+new+s[end:]
p.write_text(s)
