int main(int argc,char**argv){
 // usage: probe_feed level piece dictmode < file > segment for chunk [2576,4356)
 int level=atoi(argv[1]); int piece=atoi(argv[2]); int dictmode=atoi(argv[3]);
 unsigned char *data=NULL; size_t len=0,cap=0; unsigned char buf[65536]; size_t n;
 while((n=fread(buf,1,sizeof buf,stdin))>0){ if(len+n>cap){cap=(len+n)*2+100;data=realloc(data,cap);} memcpy(data+len,buf,n);len+=n;}
 size_t start=2576,end=4356;
 z_stream s; memset(&s,0,sizeof s); deflateInit2(&s,level,Z_DEFLATED,-15,8,0);
 if(dictmode==0){ deflateSetDictionary(&s,data,start); }
 else if(dictmode==1){ unsigned char *d=calloc(32768,1); memcpy(d+32768-start,data,start); deflateSetDictionary(&s,d,32768); }
 unsigned char *out=malloc(100000);
 size_t pos=start;
 int first=1;
 while(pos<end){
   size_t take=end-pos; if(piece>0 && take>(size_t)piece) take=piece;
   int last=(pos+take==end);
   s.next_in=data+pos; s.avail_in=take; s.next_out=out; s.avail_out=100000;
   int flush = last? Z_BLOCK : Z_NO_FLUSH;
   int r=deflate(&s,flush);
   fwrite(out,1,100000-s.avail_out,stdout);
   pos+=take;
   if(last){
     unsigned pending;int bits; deflatePending(&s,&pending,&bits);
     fprintf(stderr,"ret=%d pending=%u bits=%d avail_in=%u\n",r,pending,bits,s.avail_in);
   }
 }
 deflateEnd(&s); return 0;
}
