   reads one block, truncates it at the last rsync boundary within the
   block (if any), and records the rsync segment lengths within the job;
   otherwise it reads a single chunk (a block, or one rsync segment). */
static void read_job(CompressCtx *cc, CompJob *job, int *more, int sustained_rsync) {
    job->segs = NULL; job->nsegs = 0;
    if (!sustained_rsync) {
        read_chunk(cc, &job->in, more);
        job->segs = xmalloc(sizeof(size_t));
        job->segs[0] = job->in.len;
        job->nsegs = 1;
        return;
    }
    Buf *b = &job->in;
    b->len = 0;
    int hit_eof = 0;
    while (b->len < block_size) {
        size_t want = block_size - b->len;
        if (want > 262144) want = 262144;
        buf_reserve(b, b->len + want);
        size_t n = rread(cc->reader, b->data + b->len, want);
        if (n == 0) { hit_eof = 1; break; }
        b->len += n;
    }
    int has_more;
    if (hit_eof) {
        has_more = 0;
    } else {
        int c = rgetc2(cc->reader);
        if (c < 0) { has_more = 0; hit_eof = 1; }
        else { unsigned char uc = (unsigned char)c; runread(cc->reader, &uc, 1); has_more = 1; }
    }
    /* Scan for rsync boundaries with a local hash state. */
    unsigned hash = cc->rsync_hash;
    uint64_t gpos = cc->rsync_pos;
    size_t *bounds = NULL;
    int nb = 0, bcap = 0;
    for (size_t i = 0; i < b->len; i++) {
        hash = ((hash << 1) ^ b->data[i]) & 0xFFF;
        gpos++;
        if (gpos >= 12 && hash == 0x7FF) {
            if (nb == bcap) { bcap = bcap ? bcap * 2 : 16; bounds = xrealloc(bounds, (size_t)bcap * sizeof(size_t)); }
            bounds[nb++] = i + 1;
        }
    }
    size_t job_end = b->len;
    if (has_more && nb > 0)
        job_end = bounds[nb - 1];
    /* Commit the hash state only up to job_end. */
    if (has_more && nb > 0 && job_end == bounds[nb - 1]) {
        cc->rsync_hash = 0x7FF;
        cc->rsync_pos += job_end;
        /* nb boundaries are all <= job_end */
    } else {
        cc->rsync_hash = hash;
        cc->rsync_pos = gpos;
    }
    /* Push back the tail beyond job_end. */
    if (job_end < b->len) {
        runread(cc->reader, b->data + job_end, b->len - job_end);
        b->len = job_end;
        has_more = 1;
    }
    *more = has_more;
    /* Build the segment length list up to job_end. */
    size_t seg_start = 0;
    int segcap = 0;
    for (int i = 0; i < nb && bounds[i] <= job_end; i++) {
        if (bounds[i] == job_end && has_more && i == nb - 1) break; /* final segment below */
        if (bounds[i] > seg_start && bounds[i] < job_end) {
