            job->segs[job->nsegs++] = bounds[i] - seg_start;
            seg_start = bounds[i];
        }
    }
    if (job->nsegs == segcap) { segcap = segcap ? segcap * 2 : 16; job->segs = xrealloc(job->segs, (size_t)segcap * sizeof(size_t)); }
    job->segs[job->nsegs++] = job_end - seg_start;
    free(bounds);
}

