#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
static unsigned char *outbuf; static int outcap;
static void call(z_stream *s,int flush){ int r; do { s->next_out=outbuf; s->avail_out=outcap; r=deflate(s,flush); fwrite(outbuf,1,outcap-s->avail_out,stdout); } while(s->avail_in>0 || s->avail_out==0); (void)r; }
int main(int argc,char**argv){
 int mode=atoi(argv[1]); outcap=atoi(argv[2]); outbuf=malloc(outcap);
 unsigned char *data=NULL; size_t len=0,cap=0; unsigned char buf[65536]; size_t n;
 while((n=fread(buf,1,sizeof buf,stdin))>0){ if(len+n>cap){cap=(len+n)*2+100;data=realloc(data,cap);} memcpy(data+len,buf,n);len+=n;}
 z_stream s; memset(&s,0,sizeof s); deflateInit2(&s,0,Z_DEFLATED,-15,8,0);
 for(size_t off=0; off<len; ){
   size_t take=len-off; if(take>131072) take=131072;
   int last=(off+take==len);
   s.next_in=data+off; s.avail_in=take;
   if(mode==0){ call(&s,last?Z_FINISH:Z_BLOCK); }
   else if(mode==1){ call(&s,Z_NO_FLUSH); if(!last){ s.avail_in=0; call(&s,Z_BLOCK);} else {s.avail_in=0; call(&s,Z_FINISH);} }
   else if(mode==2){ call(&s,Z_NO_FLUSH); if(!last){s.avail_in=0; call(&s,Z_SYNC_FLUSH);} else {s.avail_in=0; call(&s,Z_FINISH);} }
   else if(mode==3){ call(&s,last?Z_FINISH:Z_NO_FLUSH); }
   else if(mode==4){ call(&s,Z_NO_FLUSH); if(last){s.avail_in=0;call(&s,Z_FINISH);} }
   off+=take;
 }
 deflateEnd(&s); return 0;
}
